/* Desktop parity: product stack cards in Transacciones should match the mobile card design language. */
@media (min-width: 768px) {
  .transactions-modal .pt-stack-carousel {
    width: 100% !important;
    min-height: 248px !important;
    height: 248px !important;
  }

  .transactions-modal .pt-item.pt-item-stack {
    top: 50% !important;
    left: 50% !important;
    width: calc(100% - 44px) !important;
    max-width: calc(100% - 44px) !important;
    height: calc(100% - 34px) !important;
    overflow: hidden !important;
    padding: 14px 16px !important;
    gap: 4px !important;
    border-radius: 22px !important;
    background: linear-gradient(180deg, rgba(122, 145, 174, 0.78), rgba(110, 131, 159, 0.74)) !important;
    border: 1px solid rgba(214, 226, 238, 0.3) !important;
    box-shadow: 0 10px 26px rgba(7, 12, 20, 0.28) !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
  }

  .transactions-modal .pt-item.pt-item-stack:not(.is-top) {
    opacity: calc(1 - (var(--pt-stack-idx, 0) * 0.14)) !important;
  }

  .transactions-modal .pt-item.pt-item-stack:not(.is-top) .pt-item-name,
  .transactions-modal .pt-item.pt-item-stack:not(.is-top) .pt-item-bank,
  .transactions-modal .pt-item.pt-item-stack:not(.is-top) .pt-item-status,
  .transactions-modal .pt-item.pt-item-stack:not(.is-top) .pt-item-meta,
  .transactions-modal .pt-item.pt-item-stack:not(.is-top) .pt-item-meta span,
  .transactions-modal .pt-item.pt-item-stack:not(.is-top) .pt-item-top {
    opacity: 0.28 !important;
    filter: blur(3px) !important;
  }

  .transactions-modal .pt-item.pt-item-stack .pt-item-name {
    font-size: clamp(22px, 2.2vw, 30px) !important;
    line-height: 1.05 !important;
    letter-spacing: -0.035em !important;
  }

  .transactions-modal .pt-item.pt-item-stack .pt-item-status {
    font-size: 10px !important;
    letter-spacing: 0.12em !important;
  }

  .transactions-modal .pt-item.pt-item-stack .pt-item-bank {
    font-size: 11px !important;
    letter-spacing: 0.2em !important;
  }

  .transactions-modal .pt-item.pt-item-stack .pt-item-meta {
    margin-top: 10px !important;
    font-size: 10px !important;
    letter-spacing: 0.06em !important;
  }

  .transactions-modal .pt-stack-nav {
    margin-top: 12px !important;
    justify-content: center !important;
    align-items: center !important;
    position: static !important;
  }

  .transactions-modal .pt-stack-nav .continue-ghost {
    min-width: 56px !important;
    min-height: 40px !important;
  }
}

