/* ─── Layout variables ──────────────────────────── */
.agent-layout {
  --chat-bg:        var(--bg-elevated);
  --bubble-user-bg: var(--accent);
  --bubble-user-fg: #ffffff;
  --bubble-ai-bg:   var(--bg-secondary);
  --bubble-ai-fg:   var(--fg);
  --input-bg:       var(--bg-overlay);
  --panel-bg:       var(--bg-secondary);
  --rail-bg:        var(--bg-secondary);
  --bubble-maxw:    72%;
  --bubble-user-maxw: 68%;
  --artifact-maxw:  80%;
  --doc-maxw:       600px;
  --chart-height:   clamp(240px, 40vh, 480px);

  position: relative;
  display: grid;
  grid-template-columns: 1fr 52px 280px;
  grid-template-rows: 1fr;
  gap: 12px;
  width: 100%;
  height: 100vh;
  max-height: 100vh;
  padding: 12px 12px 12px 16px;
  background: transparent;
  /* Bloquear swipe/bounce/resize/zoom en la pagina del agente */
  overflow: hidden;
  overscroll-behavior: none;
  touch-action: manipulation; /* bloquea double-tap zoom, permite tap y scroll internos */
  transition: grid-template-columns 0.32s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

