/* ================================================= */
/* CHAT SECTION                                      */
/* ================================================= */

.agent-chat {
  min-height: 0;
  height: 100%;
  display: flex;
  flex-direction: column;
  position: relative;
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  background: transparent;
  box-shadow: var(--shadow-md);
  overflow: hidden;
}

.chat-monochrome-toggle {
  width: 34px;
  height: 34px;
  border-radius: 999px;
  border: 1px solid rgba(198, 219, 232, 0.24);
  background: rgba(10, 16, 24, 0.58);
  color: rgba(236, 243, 248, 0.92);
  font-size: 0;
  font-weight: 700;
  letter-spacing: 0.05em;
  line-height: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

.chat-monochrome-toggle--floating {
  position: absolute;
  top: calc(env(safe-area-inset-top) + 10px);
  right: 10px;
  z-index: 12;
}

.chat-monochrome-toggle--inline {
  position: static;
  flex: 0 0 auto;
}

.chat-monochrome-toggle:hover {
  border-color: rgba(214, 230, 242, 0.34);
  background: rgba(13, 20, 30, 0.74);
}

.chat-monochrome-toggle.is-active {
  background: rgba(240, 244, 247, 0.95);
  color: rgba(11, 15, 20, 0.95);
  border-color: rgba(240, 244, 247, 0.95);
}

.mono-toggle-icon {
  width: 14px;
  height: 14px;
  display: block;
}

.mono-toggle-icon__ring {
  fill: none;
  stroke: rgba(238, 244, 248, 0.95);
  stroke-width: 2;
}

.mono-toggle-icon__half {
  fill: rgba(238, 244, 248, 0.95);
}

.mono-toggle-icon__split {
  stroke: rgba(15, 22, 31, 0.9);
  stroke-width: 1.2;
  stroke-linecap: round;
}

.layout-mode-toggle.monochrome-toggle .mono-toggle-icon {
  width: 13px;
  height: 13px;
}

@media (max-width: 767px) {
  .chat-monochrome-toggle--floating {
    top: calc(env(safe-area-inset-top) + 12px) !important;
    right: 12px !important;
    z-index: 40 !important;
  }
}

