}

.chat-sheet-tab.is-active {
  border-color: rgba(134, 176, 207, 0.6);
  background:
    linear-gradient(180deg, rgba(33, 55, 77, 0.88), rgba(25, 44, 63, 0.9));
  box-shadow:
    0 10px 24px rgba(5, 14, 23, 0.42),
    inset 0 1px 0 rgba(214, 230, 241, 0.14);
}

/* Toggle group */
.header-toggle-group {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.layout-mode-toggle {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  border: 1px solid rgba(198, 219, 232, 0.16);
  background:
    linear-gradient(180deg, rgba(255,255,255,0.1), rgba(255,255,255,0.03)),
    rgba(11, 17, 25, 0.48);
  color: rgba(239, 244, 248, 0.88);
  font-size: 13px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background var(--transition), color var(--transition), border-color var(--transition), box-shadow var(--transition);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  box-shadow: 0 12px 24px rgba(0,0,0,0.12), inset 0 1px 0 rgba(255,255,255,0.06);
}

.layout-mode-toggle:hover {
  background:
    linear-gradient(180deg, rgba(179, 208, 228, 0.14), rgba(255,255,255,0.05)),
    rgba(15, 22, 31, 0.58);
  color: #ffffff;
  border-color: rgba(183, 209, 227, 0.28);
}

.monochrome-toggle {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.04em;
}

.agent-layout.is-monochrome .monochrome-toggle {
  background: var(--fg);
  color: var(--bg);
  border-color: var(--fg);
}

/* Header text */
.agent-chat-header h1 {
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--fg);
  margin: 0 0 2px;
  max-width: none;
  text-align: left;
}

.chat-brand-title-row:hover,
.chat-brand-title-row:focus-visible {
  background: none !important;
  background-color: transparent !important;
  box-shadow: none !important;
  border: 0 !important;
  transform: none !important;
  outline: none !important;
}

.agent-chat-header p.muted {
  font-size: 12px;
  color: var(--fg-tertiary);
  margin: 0 0 8px;
  max-width: none;
  letter-spacing: 0;
  text-transform: none;
  line-height: 1.4;
}

/* Chat meta row */
.chat-meta-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.chat-id-badge {
  flex-shrink: 0;
  height: 22px;
  padding: 0 8px;
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: var(--radius-pill);
  font-size: 11px;
  font-weight: 600;
  color: var(--fg-secondary);
  display: inline-flex;
  align-items: center;
}

.chat-name-input {
  flex: 1;
  min-width: 0;
  max-width: 200px;
  height: 28px;
  padding: 0 10px;
  background: var(--bg-secondary);
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  font-size: 12px;
  font-weight: 500;
  color: var(--fg);
  width: auto;
  transition: border-color var(--transition), box-shadow var(--transition);
}

.chat-delete-btn {
  flex-shrink: 0;
  height: 26px;
  padding: 0 10px;
  border-radius: 999px;
  border: 1px solid rgba(255, 145, 145, 0.34);
  background: rgba(88, 18, 18, 0.2);
  color: rgba(255, 198, 198, 0.92);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.01em;
  cursor: pointer;
  transition: background var(--transition), border-color var(--transition), color var(--transition);
}

.chat-delete-btn:hover {
  background: rgba(128, 28, 28, 0.3);
  border-color: rgba(255, 167, 167, 0.52);
  color: rgba(255, 224, 224, 0.98);
}

.chat-name-input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft);
  outline: none;
}

.chat-name-input::placeholder {
  color: var(--fg-tertiary);
}

/* ─── Chat body ──────────────────────────────────── */

.agent-chat-body {
  min-height: 0;
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  background: transparent; /* fondo viene del animated-bg global */
  overflow: hidden;
  overflow-x: hidden !important;
  position: relative;
  overscroll-behavior-x: none !important;
  touch-action: pan-y !important;
}

.agent-chat-body > * {
  position: relative;
  z-index: 1;
}

/* Thread entrance */
.agent-chat.active-chat-1 .agent-chat-body,
.agent-chat.active-chat-2 .agent-chat-body,
.agent-chat.active-chat-3 .agent-chat-body {
  animation: threadFadeIn 0.22s ease-out;
}

@keyframes threadFadeIn {
  from { opacity: 0.5; transform: translateY(3px); }
  to   { opacity: 1;   transform: translateY(0);   }
}

/* ─── Chat pages (horizontal paging, 4 items per page) ── */

.chat-pages-outer {
  flex: 1 1 0;
  min-height: 0;
  overflow: hidden;
  position: relative;
  touch-action: pan-y;
}

.chat-pages-track {
  display: flex;
  height: 100%;
  transition: transform 0.38s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  will-change: transform;
}

/* Page indicator dots — overlaid at bottom of the pager area */
.chat-page-dots {
  position: absolute;
  bottom: 8px;
  left: 0;
  right: 0;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 6px;
  pointer-events: auto;
  z-index: 2;
}

.chat-page-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.28);
  border: none;
  cursor: pointer;
  padding: 0;
  transition: width 0.22s cubic-bezier(0.25, 0.46, 0.45, 0.94), background 0.22s;
  flex-shrink: 0;
}

.chat-page-dot.active {
  width: 22px;
  border-radius: 3px;
  background: var(--accent);
}

/* ─── Thread ─────────────────────────────────────── */

.agent-thread {
  min-height: 0;
  flex: 1 1 0;
  overflow-y: auto;
  padding: 16px 16px 24px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  scroll-padding-bottom: 80px;
}

/* Page variant — fills the track slot, pushes content to bottom */
.agent-thread.chat-page {
  flex: 0 0 100%;
  width: 100%;
  justify-content: flex-end;
}

/* ─── Bubbles ─────────────────────────────────────── */

.agent-bubble {
  max-width: var(--bubble-maxw);
  position: relative;
  animation: bubbleIn 0.2s ease-out;
  font-family: "Open Sans", -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
}

@keyframes bubbleIn {
  from { opacity: 0; transform: translateY(5px); }
  to   { opacity: 1; transform: translateY(0);   }
}

/* User bubble — Apple Premium */
.agent-bubble.user {
  align-self: flex-end;
  max-width: var(--bubble-user-maxw);
  background: linear-gradient(135deg, rgba(126, 198, 255, 0.26), rgba(205, 232, 255, 0.14));
  color: #ffffff;
  padding: 12px 16px;
  border-radius: 18px 18px 4px 18px;
  border: 1px solid rgba(186, 226, 255, 0.5);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  box-shadow:
    0 10px 24px rgba(53, 125, 178, 0.2),
    inset 0 1px 0 rgba(255, 255, 255, 0.28);
  font-size: 15px;
  line-height: 1.5;
  font-weight: 400;
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro Display", "Helvetica Neue", Helvetica, Arial, sans-serif;
  letter-spacing: -0.01em;
  word-wrap: break-word;
}

/* Assistant — transparent wrapper */
.agent-bubble.assistant {
  align-self: flex-start;
  background: rgba(5, 10, 18, 0.52);
  border: 1px solid rgba(128, 165, 198, 0.24);
  border-radius: 18px 18px 18px 4px;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  color: var(--fg);
  max-width: var(--bubble-maxw);
}

/* Loading / muted */
.agent-bubble.muted {
  align-self: flex-start;
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  color: var(--fg-secondary);
  padding: 10px 14px;
  border-radius: 18px 18px 18px 4px;
  font-size: 13px;
}

/* Artifacts and citations — wrapper has no own bg, child handles styling */
.agent-bubble.artifact,
.agent-bubble.citation {
  background: transparent;
  padding: 0;
  max-width: var(--artifact-maxw);
  align-self: flex-start;
}

/* ─── Citation bubble ────────────────────────────────────────────────── */
.citation-bubble {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 12px 14px;
  background: rgba(8, 14, 24, 0.56);
  border: 1px solid rgba(150, 198, 232, 0.24);
  border-left: 3px solid rgba(120, 190, 255, 0.72);
  border-radius: 12px;
  max-width: min(72vw, 560px);
  overflow: hidden;
  touch-action: pan-y;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

.citation-head {
  display: flex;
  align-items: center;
  gap: 8px;
}

.citation-pill {
  display: inline-flex;
  align-items: center;
  height: 18px;
  padding: 0 7px;
  background: rgba(29, 130, 210, 0.25);
  border: 1px solid rgba(29, 130, 210, 0.4);
  border-radius: 4px;
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(120, 190, 255, 0.95);
  flex-shrink: 0;
}

.citation-source {
  font-size: 11px;
  font-weight: 500;
  color: rgba(228, 239, 248, 0.72);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.citation-link {
  font-size: 12.5px;
  font-weight: 500;
  color: rgba(178, 221, 255, 0.96);
  text-decoration: none;
  line-height: 1.45;
  overflow-wrap: anywhere;
  word-break: break-word;
  transition: color 0.15s;
}

.citation-link:hover {
  color: rgba(255, 255, 255, 0.95);
  text-decoration: underline;
}

.citation-stack {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 2px;
}

.citation-toggle {
  margin-top: 10px;
  align-self: flex-start;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 11px;
  border-radius: 999px;
  border: 1px solid rgba(150, 198, 232, 0.35);
  background: rgba(12, 20, 34, 0.6);
  color: rgba(194, 229, 255, 0.95);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.02em;
  cursor: pointer;
}

.citation-toggle:hover {
  background: rgba(20, 33, 54, 0.78);
}

/* ─── Doc bubble — strengthen background ─────────────────────────────── */

/* Scrollable bubble */
.agent-bubble.is-scrollable-bubble {
  max-height: min(72vh, 720px);
  overflow: auto;
  overscroll-behavior: auto;
  -webkit-overflow-scrolling: touch;
  scroll-behavior: smooth;
  scrollbar-width: thin;
}

/* ─── LaTeX-doc (structured AI response) ────────── */

.latex-doc {
  background: transparent;
  border: none;
  border-radius: var(--radius-md);
  overflow: hidden;
  max-width: var(--bubble-maxw);
}

.agent-bubble.assistant.latex-doc.is-scrollable-bubble {
  max-height: min(72vh, 720px);
  overflow: auto;
  scrollbar-width: thin;
}

.latex-doc-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 12px 14px 11px;
  border-bottom: none;
  background: transparent;
}

.latex-doc-title {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #ffffff;
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Display", "Helvetica Neue", Helvetica, Arial, sans-serif;
}

.latex-doc-mode {
  font-size: 10px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.7);
  background: rgba(255, 255, 255, 0.05);
  padding: 3px 9px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: var(--radius-pill);
  font-weight: 500;
}

.latex-doc-body {
  padding: 14px 16px 16px;
  background: transparent;
  color: #ffffff;
  font-family: "Open Sans", -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
  font-size: 15px;
  line-height: 1.6;
  letter-spacing: -0.01em;
  max-height: min(65vh, 700px);
  overflow: auto;
  overscroll-behavior: auto;
  -webkit-overflow-scrolling: touch;
  scroll-behavior: smooth;
  scrollbar-width: thin;
}

.latex-doc-body.is-scrollable-content {
  max-height: min(65vh, 700px);
}

.latex-inline-annex {
  margin-top: 12px;
  border-top: none;
  padding-top: 12px;
}

.latex-inline-annex-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
  color: var(--fg-tertiary);
  font-size: 10px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

/* ─── Chart card (inline in chat + annex) ─────── */

.agent-chart-card {
  background: transparent;
  border: none;
  border-radius: 14px;
  overflow: hidden;
  margin: 8px 0;
}

.agent-chart-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  padding: 12px 16px 0;
  gap: 8px;
}

.agent-chart-title {
  font-size: 13px;
  font-weight: 600;
  color: var(--fg);
  margin: 0;
  line-height: 1.3;
}

.agent-chart-kind {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.08em;
  color: var(--fg-tertiary);
  background: var(--bg-tertiary, rgba(255,255,255,0.05));
  border-radius: 4px;
  padding: 2px 6px;
  flex-shrink: 0;
}

.agent-chart-subhead {
  padding: 2px 16px 0;
}

.agent-chart-subtitle {
  font-size: 11px;
  color: var(--fg-secondary);
  margin: 0;
  line-height: 1.4;
}

.agent-chart-canvas {
  height: 200px;
  padding: 10px 8px 12px;
}

@media (max-width: 767px) {
  /* Charts dentro de burbujas: scroll horizontal si no caben */
  .latex-annex-blocks {
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
  }

  .latex-annex-chart,
  .latex-annex-table {
    min-width: 280px;
  }

  .agent-chart-card {
    min-width: 280px;
  }

  .agent-chart-canvas {
    height: 180px;
    padding: 6px 4px 8px;
  }

  .agent-chart-title {
    font-size: 12px;
  }

  /* Tablas: scroll horizontal */
  .latex-annex-table {
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
  }
}

.profile-intake-strip {
  position: relative;
  z-index: 1;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.profile-intake-pill {
  padding: 6px 10px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(203, 219, 230, 0.12);
  color: rgba(236, 242, 247, 0.84);
  font-size: 0.7rem;
  line-height: 1.2;
}

.profile-intake-pill.is-stress {
  background: rgba(174, 126, 84, 0.12);
  border-color: rgba(214, 175, 117, 0.16);
}

.panel-stack-list {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 10px;
}

.panel-stack-item {
  display: block;
  padding: 8px 10px;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.045);
  color: rgba(231, 238, 244, 0.84);
  font-size: 0.75rem;
  line-height: 1.45;
}

.transactions-intelligence {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  margin-bottom: 14px;
}

.transactions-stat-card,
.transactions-summary-card {
  border-radius: 20px;
  border: 1px solid rgba(151, 180, 202, 0.28);
  background:
    linear-gradient(180deg, rgba(23, 38, 54, 0.72), rgba(15, 29, 42, 0.76)),
    rgba(10, 19, 29, 0.38);
  box-shadow:
    0 16px 32px rgba(3, 10, 18, 0.34),
    inset 0 1px 0 rgba(207, 225, 238, 0.09);
}

.transactions-stat-card {
  padding: 14px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.transactions-stat-card strong {
  font-size: 1rem;
  color: #f5f8fc;
}

.transactions-stat-label,
.transactions-summary-title {
  font-size: 0.7rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(178, 201, 217, 0.8);
}

.transactions-summary-card {
  padding: 16px 18px;
  margin-bottom: 14px;
}

.transactions-summary-card p {
  margin: 10px 0 0;
  color: rgba(212, 226, 236, 0.9);
  line-height: 1.55;
}

.transactions-keywords {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 12px;
}

.transactions-keyword-pill {
  padding: 6px 10px;
  border-radius: 999px;
  background: rgba(34, 53, 71, 0.72);
  border: 1px solid rgba(145, 177, 200, 0.24);
  color: rgba(220, 232, 241, 0.92);
  font-size: 0.72rem;
}

.transactions-products-column {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.transactions-product-card {
  display: block;
  width: 100%;
  text-align: left;
  border-radius: 20px;
  border: 1px solid rgba(148, 179, 201, 0.2);
  background:
    radial-gradient(circle at top right, rgba(98, 143, 176, 0.2), transparent 42%),
    linear-gradient(180deg, rgba(24, 40, 56, 0.62), rgba(14, 27, 40, 0.72));
  box-shadow:
    0 16px 32px rgba(0, 0, 0, 0.28),
    inset 0 1px 0 rgba(206, 224, 238, 0.08);
}

.transactions-product-card.is-active {
  border-color: rgba(127, 171, 202, 0.66);
  box-shadow:
    0 20px 36px rgba(0, 0, 0, 0.34),
    0 0 0 1px rgba(127, 171, 202, 0.24),
    inset 0 1px 0 rgba(208, 226, 239, 0.1);
}

.transactions-product-card.add-card {
  cursor: pointer;
  padding: 16px;
}

.transactions-product-main {
  width: 100%;
  border: none;
  background: transparent;
  text-align: left;
  color: inherit;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 16px;
}

.transactions-product-main strong,
.transactions-product-card.add-card strong {
  font-size: 1rem;
  letter-spacing: -0.02em;
  color: rgba(245, 250, 255, 0.98);
}

.transactions-product-main p,
.transactions-product-card.add-card p {
  margin: 0;
  color: rgba(231, 239, 245, 0.9);
  line-height: 1.5;
  font-size: 0.84rem;
}

.transactions-product-eyebrow {
  font-size: 0.68rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(186, 205, 219, 0.72);
}

.transactions-product-insights {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.transactions-product-insights span {
  color: rgba(194, 216, 232, 0.86);
  font-size: 0.75rem;
}

.transactions-product-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 0 16px 14px;
}

.transactions-product-actions .continue-ghost {
  min-height: 38px;
  padding: 0 12px;
}

.pt-shell {
  display: grid;
  grid-template-columns: minmax(360px, 420px) minmax(0, 1fr);
  gap: 18px;
  padding: 0 20px 20px;
  min-height: 0;
  height: calc(100% - 8px);
}

.pt-premium-intro {
  margin: 0 20px 14px;
  padding: 12px 14px;
  border-radius: 16px;
  border: 1px solid rgba(151, 181, 203, 0.24);
  background: linear-gradient(180deg, rgba(21, 35, 49, 0.66), rgba(14, 26, 39, 0.7));
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  display: grid;
  gap: 10px;
}

.pt-premium-intro-main strong {
  display: block;
  font-size: 13px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: rgba(221, 234, 244, 0.92);
}

.pt-premium-intro-main p {
  margin: 6px 0 0;
  color: rgba(204, 221, 233, 0.88);
  line-height: 1.5;
  font-size: 13px;
}

.pt-premium-intro-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.pt-premium-intro-pills span {
  border-radius: 999px;
  border: 1px solid rgba(143, 176, 199, 0.3);
  background: rgba(30, 47, 63, 0.7);
  color: rgba(212, 226, 237, 0.92);
  padding: 5px 10px;
  font-size: 11px;
}

.pt-left,
.pt-right {
  border: 1px solid rgba(149, 180, 202, 0.26);
  border-radius: 22px;
  background: linear-gradient(180deg, rgba(20, 34, 48, 0.72), rgba(13, 25, 37, 0.78)), rgba(9, 17, 27, 0.38);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  box-shadow:
    0 18px 34px rgba(3, 11, 20, 0.36),
    inset 0 1px 0 rgba(206, 224, 238, 0.08);
}

.pt-left {
  padding: 14px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-height: 0;
  overflow: hidden;
}

.pt-right {
  padding: 16px;
  overflow: auto;
  display: flex;
