.transactions-modal .tx-library-stack-block {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  gap: 14px;
  width: 100%;
}

.pt-item.pt-item-stack {
  position: absolute;
  top: 50%;
  left: 50%;
  width: calc(100% - 44px);
  height: calc(100% - 34px);
  transform:
    translate(-50%, -50%)
    scale(calc(1 - (var(--pt-stack-idx, 0) * 0.045)))
    rotate(calc(var(--pt-stack-tilt, 0) * 1deg));
  z-index: calc(40 - var(--pt-stack-idx, 0));
  opacity: calc(1 - (var(--pt-stack-idx, 0) * 0.14));
  pointer-events: none;
  padding: 14px 16px !important;
  gap: 4px !important;
  overflow: hidden;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  justify-content: center !important;
  text-align: center !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  transition:
    transform 0.22s ease,
    border-color 0.2s ease,
    box-shadow 0.2s ease,
    opacity 0.2s ease !important;
}

.pt-item.pt-item-stack.is-top {
  pointer-events: auto;
  opacity: 1;
}

.pt-item.pt-item-stack:hover,
.pt-item.pt-item-stack:focus-visible {
  transform:
    translate(-50%, -50%)
    scale(calc((1 - (var(--pt-stack-idx, 0) * 0.045)) * 1.018))
    rotate(calc(var(--pt-stack-tilt, 0) * 1deg)) !important;
}

.pt-item.pt-item-stack:hover {
  box-shadow: 0 16px 30px rgba(3, 12, 21, 0.34) !important;
}

.pt-item.pt-item-stack:nth-child(1) {
  --pt-stack-tilt: -0.4;
}

.pt-item.pt-item-stack:nth-child(2) {
  --pt-stack-tilt: -5.2;
}

.pt-item.pt-item-stack:nth-child(3) {
  --pt-stack-tilt: 4.6;
}

.pt-item.pt-item-stack:nth-child(4) {
  --pt-stack-tilt: -2.8;
}

.pt-item.pt-item-stack:not(.is-top) {
}

.pt-item.pt-item-stack:not(.is-top) .pt-item-name,
.pt-item.pt-item-stack:not(.is-top) .pt-item-bank,
.pt-item.pt-item-stack:not(.is-top) .pt-item-status,
