  opacity: 0.18;
  filter: blur(4px);
}

.pt-item.pt-item-stack:not(.is-top)::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(9, 15, 24, 0.16), rgba(9, 15, 24, 0.3));
  pointer-events: none;
