}

.agent-table-head {
  padding: 12px 14px 8px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.07);
}

.agent-table-title {
  font-size: 13px;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.85);
}

.agent-table-scroll {
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.agent-table {
  width: 100%;
  border-collapse: collapse;
  min-width: 300px;
}

.agent-table-th {
  padding: 8px 12px;
  text-align: left;
  font-size: 11px;
