}

.agent-table-td {
  padding: 9px 12px;
  color: rgba(255, 255, 255, 0.72);
  border-bottom: 1px solid rgba(255, 255, 255, 0.04);
  vertical-align: middle;
  line-height: 1.4;
}

.agent-table-td.is-label {
  font-weight: 500;
  color: rgba(255, 255, 255, 0.88);
}

.agent-table-tr:last-child .agent-table-td {
  border-bottom: none;
}

.agent-table-note {
