}

.questionnaire-modal {
  max-width: 720px;
}

.questionnaire-dashboard {
  padding: 0 24px 24px;
  display: grid;
  gap: 14px;
}

.questionnaire-kpi-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.questionnaire-kpi {
  border: 1px solid var(--border);
  border-radius: 14px;
  background: rgba(16, 24, 36, 0.45);
  padding: 10px 12px;
  display: grid;
  gap: 6px;
}

.questionnaire-kpi-label {
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--fg-tertiary);
}

.questionnaire-kpi strong {
  font-size: 24px;
  line-height: 1;
  color: var(--fg);
}

.questionnaire-response-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.questionnaire-response-item {
  border: 1px solid var(--border);
  border-radius: 12px;
  background: rgba(13, 19, 30, 0.48);
  padding: 9px 10px;
  display: grid;
  gap: 4px;
}

.questionnaire-response-item span {
  font-size: 11px;
  color: var(--fg-tertiary);
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.questionnaire-response-item strong {
  font-size: 13px;
  color: var(--fg);
  line-height: 1.35;
}

.questionnaire-insights {
  border: 1px solid var(--border);
  border-radius: 14px;
  background: rgba(10, 18, 30, 0.52);
  padding: 11px 12px;
}

.questionnaire-insights ul {
  margin: 8px 0 0;
  padding-left: 18px;
  display: grid;
  gap: 6px;
}

.questionnaire-insights li {
  font-size: 13px;
  color: var(--fg-secondary);
  line-height: 1.45;
}

.panel-minimal-soft {
  background: #121821 !important;
  border: 1px solid rgba(182, 208, 226, 0.1) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  box-shadow: none !important;
}

.panel-centered-content {
  display: flex !important;
  flex-direction: column !important;
  justify-content: center !important;
  align-items: center !important;
  text-align: center !important;
  gap: 10px !important;
  padding-top: 16px !important;
  padding-bottom: 16px !important;
}

.panel-centered-content .panel-text,
.panel-centered-content .panel-value,
.panel-centered-content .panel-label,
.panel-centered-content .panel-stack-list,
.panel-centered-content .panel-stack-item {
  text-align: center !important;
}

.panel-text-strong {
  font-weight: 600 !important;
}

.panel-card-note {
  font-size: 0.68rem;
  line-height: 1.35;
  color: rgba(217, 228, 238, 0.78);
  max-width: 30ch;
}

.panel-card-note-library {
  max-width: 34ch;
}

.panel-feature-copy-secondary {
  color: rgba(215, 227, 238, 0.72) !important;
  font-size: 0.68rem !important;
}

.interview-flow-submeta {
  opacity: 0.82;
  font-size: 0.68rem !important;
}

.budget-table-wrap {
  padding: 0 24px 20px;
  overflow-x: auto;
}

.budget-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

.budget-table th {
  text-align: left;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--fg-tertiary);
  padding: 8px 6px;
  border-bottom: 1px solid var(--border);
}

.budget-table td {
  padding: 7px 6px;
  border-bottom: 1px solid var(--border);
  color: var(--fg);
}

.budget-table tr:last-child td {
  border-bottom: none;
}

.budget-table input,
.budget-table select {
  height: 32px;
  min-height: 32px;
  font-size: 12px;
  padding: 0 8px;
  border-radius: var(--radius-xs);
}

.budget-kpi-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  padding: 0 24px 12px;
}

.budget-chat-card {
  margin: 0 24px 14px;
  padding: 14px;
  border-radius: 14px;
  border: 1px solid rgba(194, 214, 227, 0.16);
  background: rgba(7, 12, 22, 0.7);
}

.budget-chat-badge {
  display: inline-block;
  margin-bottom: 8px;
  font-size: 10px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--fg-tertiary);
}

.budget-chat-question {
  margin: 0;
  font-size: 21px;
  line-height: 1.25;
  color: var(--fg);
}

.budget-chat-input-row {
  margin-top: 12px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
}

.budget-chat-input-row input {
  height: 40px;
  border-radius: 10px;
  padding: 0 12px;
}

.budget-chat-log {
  margin-top: 10px;
  display: grid;
  gap: 6px;
}

.budget-chat-log-row {
  border: 1px solid rgba(194, 214, 227, 0.1);
  border-radius: 10px;
  padding: 8px 10px;
  background: rgba(255, 255, 255, 0.02);
  display: grid;
  gap: 4px;
}

.budget-chat-log-row span {
  font-size: 11px;
  color: var(--fg-secondary);
}

.budget-chat-log-row strong {
  font-size: 13px;
  color: var(--fg);
}

.budget-kpi-card {
  border: 1px solid rgba(194, 214, 227, 0.12);
  background: linear-gradient(180deg, rgba(255,255,255,0.05), rgba(255,255,255,0.02));
  border-radius: 14px;
  padding: 10px 12px;
  display: grid;
  gap: 4px;
}

.budget-kpi-label {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--fg-tertiary);
}

.budget-kpi-card strong {
  font-size: 15px;
  color: var(--fg);
}

.budget-health {
  margin: 0 24px 14px;
  padding: 12px;
  border-radius: 14px;
  border: 1px solid rgba(194, 214, 227, 0.12);
  background: rgba(8, 12, 20, 0.45);
}

.budget-health-head {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  color: var(--fg-secondary);
  margin-bottom: 8px;
}

.budget-health-track {
  height: 9px;
  border-radius: 999px;
  background: rgba(116, 152, 182, 0.16);
  overflow: hidden;
}

.budget-health-fill {
  height: 100%;
  background: linear-gradient(90deg, #89a9c5, #b2c5d8);
  border-radius: inherit;
}

.budget-health-legend {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  margin-top: 8px;
  font-size: 11px;
  color: var(--fg-tertiary);
}

.budget-top-expenses {
  margin: 0 24px 14px;
  padding: 12px;
  border-radius: 14px;
  border: 1px solid rgba(194, 214, 227, 0.12);
  background: rgba(8, 12, 20, 0.45);
}

.budget-top-title {
  font-size: 11px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--fg-tertiary);
}

.budget-top-row {
  margin-top: 10px;
}

.budget-top-meta {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  color: var(--fg-secondary);
  margin-bottom: 5px;
}

.budget-top-track {
  height: 7px;
  background: rgba(116, 152, 182, 0.16);
  border-radius: 999px;
  overflow: hidden;
}

.budget-top-fill {
  height: 100%;
  background: linear-gradient(90deg, #89a9c5, #b2c5d8);
  border-radius: inherit;
}

/* ================================================= */
/* MOBILE BOTTOM NAV                                 */
/* ================================================= */

.mobile-bottom-nav {
  display: none;
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 200;
  height: calc(56px + env(safe-area-inset-bottom));
  padding-bottom: env(safe-area-inset-bottom);
  background: var(--bg-overlay);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  border-top: 1px solid var(--border);
}

.mobile-bottom-nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-around;
  height: 56px;
  padding: 0 8px;
}

.mobile-nav-tab {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  flex: 1;
  height: 100%;
  background: transparent;
  border: none;
  cursor: pointer;
  color: var(--fg-tertiary);
  transition: color var(--transition);
  -webkit-tap-highlight-color: transparent;
  padding: 4px 8px;
}

.mobile-nav-tab.is-active {
  color: var(--accent);
}

.mobile-nav-tab svg {
  width: 22px;
  height: 22px;
  flex-shrink: 0;
}

.mobile-nav-tab span {
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.01em;
}

/* Mobile panel handle — hidden by default on desktop */
.mobile-panel-handle {
  display: none;
}

/* Mobile panel close header */
.mobile-panel-close {
  display: none;
  position: sticky;
  top: 0;
  z-index: 10;
  width: 100%;
  padding: 12px 16px;
  background: var(--bg);
  border-bottom: 1px solid var(--border);
  align-items: center;
  gap: 10px;
}

.mobile-panel-close-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  background: transparent;
  border: none;
  color: var(--accent);
  font-size: 15px;
  font-weight: 500;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

.mobile-panel-close-title {
  font-size: 17px;
  font-weight: 600;
  color: var(--fg);
  flex: 1;
  text-align: center;
}

/* Swipe dots hidden on desktop */
.mobile-chat-swipe-dots { display: none; }
.mobile-rail-subtitle { display: none; }

/* mob-col wrappers: transparent in desktop (display:contents passes children to grid) */
.mob-col { display: contents; }

/* ─── Chat swipe slide animations ──────────────── */

@keyframes chatSlideInFromRight {
  from { transform: translateX(40px); opacity: 0.5; }
  to   { transform: translateX(0);    opacity: 1;   }
}

@keyframes chatSlideInFromLeft {
  from { transform: translateX(-40px); opacity: 0.5; }
  to   { transform: translateX(0);     opacity: 1;   }
}

.agent-chat.chat-slide-left  { animation: chatSlideInFromRight 0.28s cubic-bezier(0.25,0.46,0.45,0.94); }
.agent-chat.chat-slide-right { animation: chatSlideInFromLeft  0.28s cubic-bezier(0.25,0.46,0.45,0.94); }

/* ================================================= */
/* RESPONSIVE                                        */
/* ================================================= */

/* ─── Mobile (<768px) ───────────────────────────── */

@media (max-width: 767px) {
  html.keyboard-opening,
  body.keyboard-opening {
    overflow: hidden !important;
  }

  body.keyboard-opening .global-agent-backdrop,
  body.keyboard-opening .app-shell::before,
  body.keyboard-opening .app-shell::after {
    animation: none !important;
    transform: none !important;
    transition: none !important;
    background-attachment: scroll !important;
    will-change: auto !important;
  }

  /* ── Layout: fondo único que cubre chat + panel ── */
  .agent-layout {
    display: flex !important;
    flex-direction: column !important;
    /* 12px side padding lets the background show on both sides */
    padding: 0 12px;
    gap: 0;
    /* Use 100dvh (full screen incl. safe areas) so no strip shows below panel.
       --visual-vh is still set by JS for keyboard handling via the chat flex child. */
    height: 100dvh;
    max-height: 100dvh;
    overflow: hidden;
    overscroll-behavior: none;
    touch-action: manipulation;
    background: transparent !important; /* fondo viene del animated-bg global */
  }

  /* Chat body: transparente */
  .agent-chat-body {
    background: transparent !important;
  }

  .agent-chat-body {
    padding-bottom: 0 !important;
  }

  .agent-input {
    padding: 6px 8px env(safe-area-inset-bottom) !important;
    margin-bottom: 0 !important;
  }
  .agent-chat-body::before {
    display: none !important;
  }

  /* Overlay eliminado — fondo unico viene del animated-bg global */
  .agent-layout > * {
    position: relative;
    z-index: 1;
  }

  /* Rail y subtitle: mismo tono que las burbujas del agente */
  .agent-divider-rail {
    background: var(--bg-elevated) !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    border-bottom: none !important;
  }

  .mobile-rail-subtitle {
    background: var(--bg-elevated) !important;
    border-top: 1px solid rgba(255,255,255,0.06) !important;
  }

  /* ── Knowledge rail: horizontal strip at top ── */
  .agent-divider-rail {
    display: flex !important;
    order: -1;
    flex: 0 0 auto !important;
    height: auto !important;
    min-height: 0 !important;
    width: 100%;
    flex-direction: column;
    border-bottom: 1px solid var(--border);
    background: var(--bg-secondary);
    z-index: 10;
  }

  /* Subtitle — arriba del rail card (order -1) — compacto */
  .mobile-rail-subtitle {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    padding: 4px 16px 3px;
    border-bottom: 1px solid rgba(255,255,255,0.06);
    border-top: none;
    background: var(--bg-elevated) !important;
    order: -1;
  }

  .mobile-rail-subtitle-title {
    font-size: 13px;
    font-weight: 700;
    letter-spacing: 0.03em;
    color: #ffffff;
    white-space: nowrap;
  }

  .mobile-rail-subtitle-badge {
    font-size: 9px;
    font-weight: 600;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: var(--accent);
    background: rgba(99, 152, 255, 0.15);
    border: 1px solid rgba(99, 152, 255, 0.3);
    border-radius: 4px;
    padding: 1px 5px;
    white-space: nowrap;
  }

  .mobile-rail-subtitle-memory {
    font-size: 9px;
    font-weight: 500;
    color: #4ade80;
    white-space: nowrap;
    letter-spacing: 0.02em;
  }

  .mobile-rail-subtitle-sep {
    font-size: 9px;
    color: var(--fg-tertiary);
  }

  .mobile-rail-subtitle-desc {
    font-size: 10px;
    color: var(--fg-secondary);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    flex: 1;
    min-width: 0;
  }

  .knowledge-rail-card {
    flex-direction: row !important;
    flex: 0 0 26px;
    width: 100%;
    height: 26px;
    padding: 0 12px !important;
    gap: 10px !important;
    border-radius: 0 !important;
    border: none !important;
    background: var(--bg-elevated) !important;
    align-items: center !important;
    overflow: hidden;
    text-align: left !important;
    position: relative !important;
  }

  /* Barra de progreso — color animado mostaza ↔ azul grisáceo gradual */
  .knowledge-rail-card::before {
    content: '' !important;
    position: absolute !important;
    top: 0 !important;
    left: 0 !important;
    right: auto !important;
    bottom: 0 !important;
    width: var(--rail-glow-h, 0%) !important;
    height: 100% !important;
    transition: width 1.2s cubic-bezier(0.25, 0.46, 0.45, 0.94) !important;
    clip-path: none !important;
    background-color: rgba(40,110,115,0.22) !important;
    -webkit-mask-image: linear-gradient(to right, black 0%, black 58%, transparent 100%) !important;
    mask-image: linear-gradient(to right, black 0%, black 58%, transparent 100%) !important;
    animation: railColorShift 10s linear infinite !important;
    opacity: 1 !important;
  }

  /* Shimmer sutil encima */
  .knowledge-rail-card::after {
    content: '' !important;
    position: absolute !important;
    inset: 0 !important;
    background: linear-gradient(to right, transparent 0%, rgba(255,255,255,0.08) 50%, transparent 100%) !important;
    animation: shimmerSlideH 3.5s ease-in-out infinite !important;
    pointer-events: none !important;
    z-index: 1 !important;
  }

  /* Todos los hijos del rail sobre el fondo */
  .knowledge-rail-card > * {
    position: relative !important;
    z-index: 2 !important;
  }

  .knowledge-rail-label {
    writing-mode: horizontal-tb !important;
    transform: none !important;
    font-size: 10px !important;
    white-space: nowrap;
    opacity: 0.65;
    flex-shrink: 0;
  }

  /* Ocultar la barra track — el fondo del card ya ES la barra */
  .knowledge-rail-track-wrap {
    display: none !important;
  }

  .knowledge-rail-dot { display: none !important; }

  /* Score: inline row */
  .knowledge-rail-score {
    flex-direction: row !important;
    gap: 5px !important;
    align-items: baseline !important;
    flex-shrink: 0;
  }

  .knowledge-rail-value {
    font-size: 15px !important;
    line-height: 1 !important;
    color: #ffffff !important;
    font-weight: 700 !important;
  }
  .knowledge-rail-stage {
    font-size: 10px !important;
    max-width: none !important;
    text-align: left !important;
    color: rgba(255,255,255,0.80) !important;
  }
  .knowledge-rail-meta  {
    font-size: 10px !important;
    flex-shrink: 0;
    color: rgba(255,255,255,0.65) !important;
  }
  .knowledge-rail-label {
    color: rgba(255,255,255,0.65) !important;
  }

  .knowledge-rail-cta {
    font-size: 10px !important;
    opacity: 1 !important;
    background: rgba(70, 130, 180, 0.28) !important;
    border: 1px solid rgba(70, 130, 180, 0.60) !important;
    color: #a8d4f5 !important;
    border-radius: 8px;
    padding: 3px 10px;
    min-height: 28px;
    display: flex;
    align-items: center;
    flex-shrink: 0;
  }

  /* Popup appears below rail */
  .knowledge-popup {
    position: fixed !important;
    top: 78px !important;
    right: 10px !important;
    left: 10px !important;
    width: auto !important;
  }

  /* Chat: transparente — el fondo del layout se ve a través */
  .agent-chat {
    flex: 1;
    min-height: 0;
    border-radius: 0;
    border: none;
    border-bottom: none;
    box-shadow: none;
    background: transparent !important;
  }

  /* Header: sin padding para que controls-row quede de borde a borde */
  .agent-chat-header {
    background: transparent !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    border-bottom: 1px solid rgba(255,255,255,0.08) !important;
    padding: 0 !important;
  }

  /* Título: oculto en mobile para ganar espacio */
  .agent-chat-header h1 {
    display: none !important;
  }
  .agent-chat-header p.muted {
    display: none !important;
  }

  /* Panel handle — draggable */
  .mobile-panel-handle {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 6px 12px 5px;
    border-top: 1px solid rgba(255,255,255,0.08);
    border-bottom: 1px solid rgba(255,255,255,0.06);
    flex-shrink: 0;
    gap: 8px;
    background: transparent;
    cursor: ns-resize;
    touch-action: none;
    -webkit-tap-highlight-color: transparent;
    user-select: none;
  }

  /* Panel con transicion fluida salvo durante el drag activo */
  .agent-panel {
    transition: flex-basis 0.32s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  }
  .agent-layout.keyboard-opening .agent-panel,
  .agent-layout.keyboard-opening .agent-chat,
  .agent-layout.keyboard-opening .agent-chat-body,
  .agent-layout.keyboard-opening .agent-input-shell {
    transition: none !important;
  }
  .agent-panel.is-dragging {
    transition: none !important;
  }

  /* Panel: compact 2-row grid at bottom */
  .agent-panel {
    display: flex !important;
    flex-direction: column;
    flex: 0 0 var(--mobile-panel-h, 69px);
    min-height: 0;
    background: var(--panel-bg);
    border-top: 1px solid var(--border);
    overflow: hidden;
    transition: flex-basis 0.32s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    position: relative;
  }

  /* Sin fondo propio — continúa el fondo del layout */
  .agent-panel {
    background: transparent !important;
    border-top: 1px solid rgba(255,255,255,0.10) !important;
    overflow: visible !important;
  }
  .agent-panel::before {
    display: none !important;
  }
  /* panel-grid necesita overflow-x para el scroll horizontal */
  .agent-panel .panel-grid {
    overflow-x: auto !important;
    overflow-y: visible !important;
  }

