  }

  .mobile-panel-toggle {
    display: none;
  }

  /* ── Mobile panel: flex-row scroll with mob-col wrappers ── */
  .agent-panel .panel-grid {
    display: flex !important;
    flex-direction: row !important;
    flex-wrap: nowrap !important;
    align-items: stretch !important;
    gap: 8px !important;
    overflow-x: auto !important;
    overflow-y: hidden !important;
    padding: 8px 12px 10px !important;
    -webkit-overflow-scrolling: touch !important;
    scrollbar-width: none !important;
    flex: 1 !important;
    min-height: 0 !important;
    scroll-snap-type: x proximity !important;
    scroll-padding-inline: 12px !important;
    scroll-behavior: smooth !important;
    overscroll-behavior-x: contain !important;
    touch-action: pan-x !important;
  }

  .agent-layout.mobile-panel-expanded .agent-panel .panel-grid {
    touch-action: pan-x pan-y !important;
    overscroll-behavior-y: contain !important;
  }

  .agent-panel .panel-grid::-webkit-scrollbar { display: none; }

  /* mob-col: todos iguales — una sola fila de rectángulos */
  .agent-panel .mob-col,
  .agent-panel .mob-col-wide,
  .agent-panel .mob-col-narrow {
    display: flex !important;
    flex-direction: column !important;
    flex-shrink: 0 !important;
    width: min(212px, 74vw) !important;
    scroll-snap-align: start !important;
    scroll-snap-stop: always !important;
    /* alto viene de align-items:stretch en panel-grid */
  }

  /* Único hijo ocupa todo el alto de la columna */
  .agent-panel .mob-col > * {
    flex: 1 1 0 !important;
    min-height: 0 !important;
    width: 100% !important;
    min-width: 0 !important;
    max-width: 100% !important;
    box-sizing: border-box !important;
    overflow: hidden !important;
  }

  /* Biblioteca: el mob-col permite overflow vertical para scroll */
  .agent-panel .mob-col:has(.panel-pos-library) {
    overflow: visible !important;
  }

  /* Biblioteca: scrollable verticalmente en mobile */
  .agent-panel .mob-col .panel-pos-library {
    overflow-y: auto !important;
    overflow-x: hidden !important;
    -webkit-overflow-scrolling: touch !important;
    overscroll-behavior: contain !important;
  }

  .agent-panel .panel-pos-library .panel-text {
    flex: 1 1 0 !important;
    min-height: 0 !important;
    display: flex !important;
    flex-direction: column !important;
    overflow-y: auto !important;
    -webkit-overflow-scrolling: touch !important;
    padding: 0 !important;
  }

  .agent-panel .panel-pos-library .report-list {
    display: flex !important;
    flex-direction: column !important;
    gap: 3px !important;
    overflow-y: visible !important;
    flex-shrink: 0 !important;
  }

  .agent-panel .panel-pos-library .reports-grid {
    gap: 4px !important;
    margin-bottom: 6px !important;
    flex-shrink: 0 !important;
  }

  /* Modo cognitivo: negro marcado + degradado azul-ámbar en movimiento */
  .agent-panel .panel-mode-cognitive {
    padding: 8px !important;
    position: relative !important;
    overflow: hidden !important;
    background: rgba(30,30,50,0.30) !important;
    backdrop-filter: none !important;
    isolation: isolate !important;
  }
  /* imagen fija desaturada y oscura */
  .agent-panel .panel-mode-cognitive::before {
    opacity: 1 !important;
    background-size: cover !important;
    background-position: center 70% !important;
    filter: grayscale(1) contrast(2.8) brightness(0.38) saturate(0) !important;
    z-index: 0 !important;
    animation: none !important;
  }
  /* overlay: azul mate → amarillo mate cada 5s */
  .agent-panel .panel-mode-cognitive::after {
    content: '' !important;
    position: absolute !important;
    inset: 0 !important;
    animation: cognitiveColor 5s ease-in-out infinite !important;
    mix-blend-mode: color !important;
    z-index: 1 !important;
    pointer-events: none !important;
    opacity: 0.65 !important;
  }

  .agent-panel .panel-mode-cognitive {
    box-shadow: inset 0 0 0 1000px rgba(30,30,50,0.35) !important;
    animation: cognitiveBlockInvert 14s linear infinite !important;
  }
  .agent-panel .panel-mode-cognitive .panel-label,
  .agent-panel .panel-mode-cognitive .panel-value {
    position: relative !important;
    z-index: 2 !important;
    text-shadow: 0 1px 4px rgba(0,0,0,0.8) !important;
    display: block !important;
  }

