  }

  /* Input: fondo transparente (continúa el chat body), elementos internos oscuros */
  .agent-input {
    padding: 3px 8px;
    padding-bottom: calc(3px + env(safe-area-inset-bottom));
    background: transparent !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    border-top: 1px solid rgba(255,255,255,0.12) !important;
  }

  .agent-input textarea {
    font-size: 16px; /* 16px evita auto-zoom en iOS Safari al hacer focus */
    min-height: 20px;
    max-height: 52px;
    padding: 6px 10px;
    line-height: 1.45;
    background: rgba(255,255,255,0.08) !important;
    border: none !important;
    border-bottom: 1px solid rgba(255,255,255,0.15) !important;
    color: #ffffff !important;
    border-radius: 0 !important;
    outline: none !important;
  }

  .agent-input textarea::placeholder {
    color: var(--fg-tertiary) !important;
  }

  .agent-input .controls {
    padding: 2px 8px 1px;
    gap: 4px;
    margin-top: 3px;
  }

  .controls .continue-button {
    padding: 2px 8px;
    font-size: 11px;
    height: 22px;
    background: var(--bg-secondary) !important;
    border: 1px solid var(--border) !important;
    color: var(--fg-secondary) !important;
    backdrop-filter: none !important;
  }

  /* Hide tip text on mobile — saves ~24px */
  .agent-input .hint {
    display: none;
  }

  .mobile-bottom-nav { display: none; }

  /* ── Light mode fixes: hardcoded whites → dark tokens ── */
  @media (prefers-color-scheme: light) {
    .mobile-rail-subtitle-title {
      color: var(--fg) !important;
    }
    .knowledge-rail-value {
      color: var(--fg) !important;
    }
    .knowledge-rail-stage {
      color: var(--fg-secondary) !important;
    }
    .knowledge-rail-meta {
      color: var(--fg-tertiary) !important;
    }
    .knowledge-rail-label {
      color: var(--fg-tertiary) !important;
      opacity: 1 !important;
    }
    .agent-chat-header h1 {
      color: var(--fg) !important;
    }
    .agent-panel .panel-label {
      color: var(--fg) !important;
      -webkit-text-fill-color: var(--fg) !important;
    }
    .agent-panel .panel-value {
      color: var(--fg-secondary) !important;
    }
    .agent-panel .panel-feature-copy,
    .agent-panel .panel-feature-label,
    .agent-panel .interview-flow-title,
    .agent-panel .interview-flow-meta,
    .agent-panel .interview-flow-label {
      color: var(--fg) !important;
      -webkit-text-fill-color: var(--fg) !important;
    }
    /* Objective / next block title */
    .agent-panel .panel-pos-objective .panel-label,
    .agent-panel .panel-pos-next .panel-label {
      color: var(--fg) !important;
      -webkit-text-fill-color: var(--fg) !important;
    }
    /* Any remaining white text inside panel blocks */
    .agent-panel .panel-card,
    .agent-panel .panel-feature-card,
    .agent-panel .interview-flow-card,
    .agent-panel .recent-library-card {
      color: var(--fg) !important;
    }
    /* Rail background: keep elevated but ensure contrast */
    .knowledge-rail-card {
      background: var(--bg-elevated) !important;
    }
    .knowledge-rail-cta {
      color: var(--accent) !important;
    }
  }

  /* ── Typography — Apple SF Pro style ─────────────── */

  /* Chat header title */
  .agent-chat-header h1 {
    font-size: 17px !important;
    font-weight: 600 !important;
    letter-spacing: -0.022em !important;
    line-height: 1.18 !important;
  }

  /* Rail title */
  .mobile-rail-subtitle-title {
    font-size: 15px !important;
    font-weight: 700 !important;
    letter-spacing: -0.028em !important;
    line-height: 1.1 !important;
  }

  /* Rail subtitle label */
  .mobile-rail-subtitle-sub {
    font-size: 11px !important;
    font-weight: 400 !important;
    letter-spacing: 0.005em !important;
    opacity: 0.55 !important;
  }

  /* Knowledge bar item label */
  .knowledge-rail-label {
    font-size: 10px !important;
    font-weight: 500 !important;
    letter-spacing: -0.01em !important;
  }

  /* Panel block label (título grande) */
  .agent-panel .panel-label {
    font-size: 14px !important;
    font-weight: 600 !important;
    letter-spacing: -0.02em !important;
    line-height: 1.15 !important;
  }

  /* Panel block value (texto pequeño debajo) */
  .agent-panel .panel-value {
    font-size: 10px !important;
    font-weight: 400 !important;
    letter-spacing: -0.008em !important;
    line-height: 1.35 !important;
  }

  /* Bubble text */
.message-bubble,
.agent-message {
  font-size: 15px !important;
  font-weight: 400 !important;
  letter-spacing: -0.012em !important;
  line-height: 1.5 !important;
  font-family: "Open Sans", -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif !important;
}

  /* Input textarea */
  .agent-input textarea {
    font-size: 15px !important;
    font-weight: 400 !important;
    letter-spacing: -0.01em !important;
    line-height: 1.45 !important;
  }

  /* Numeric values — tabular */
  .panel-value,
  .knowledge-rail-score,
  .coherence-value {
    font-variant-numeric: tabular-nums !important;
    font-feature-settings: "tnum" 1 !important;
  }
}

@keyframes shimmerSlideH {
  0%   { transform: translateX(-200%); }
  100% { transform: translateX(200%); }
}

/* Knowledge rail — mostaza ↔ azul grisáceo, background-color interpolado suavemente */
@keyframes railColorShift {
  0%, 100% { background-color: rgba(40,110,115,0.22); }
  50%      { background-color: rgba(30,90,100,0.19); }
}

/* Knowledge rail — ola en el borde derecho de la barra de progreso */
@keyframes railWave {
  0%   { clip-path: polygon(0 0, 100% 0, 100% 20%, calc(100% - 10px) 50%, 100% 80%, 100% 100%, 0 100%); }
  33%  { clip-path: polygon(0 0, 100% 0, 100% 28%, calc(100% - 8px) 52%, 100% 76%, 100% 100%, 0 100%); }
  66%  { clip-path: polygon(0 0, 100% 0, 100% 18%, calc(100% - 12px) 48%, 100% 82%, 100% 100%, 0 100%); }
  100% { clip-path: polygon(0 0, 100% 0, 100% 20%, calc(100% - 10px) 50%, 100% 80%, 100% 100%, 0 100%); }
}

/* Modo cognitivo — 3s normal → 3s negativo, lineal continuo */
@keyframes cognitiveBlockInvert {
  0%   { filter: invert(0); }
  50%  { filter: invert(1); }
  100% { filter: invert(0); }
}

/* Modo cognitivo — #4682B4 → #4A6B8A → amarillo mate, 5s */
@keyframes cognitiveColor {
  0%   { background: #4682B4; }
  40%  { background: #4682B4; }
  48%  { background: #4A6B8A; }
  52%  { background: #b89a00; }
  92%  { background: #c9a800; }
  100% { background: #4682B4; }
}

/* ─── Tablet (768px-1023px) ─────────────────────── */

@media (min-width: 768px) and (max-width: 1023px) {
  .agent-layout {
    grid-template-columns: 1fr 48px !important;
    padding: 10px;
  }

  .agent-panel {
    display: none !important;
  }

  .agent-layout.is-panel-stage-1 .agent-panel,
  .agent-layout.is-panel-stage-2 .agent-panel {
    display: flex !important;
    flex-direction: column;
  }

  .agent-layout.is-panel-stage-1 {
    grid-template-columns: 1fr 48px 260px !important;
  }

  .agent-layout.is-panel-stage-2 {
    grid-template-columns: 1fr 48px 300px !important;
  }
}

/* ─── Large desktop (≥1440px) ───────────────────── */

@media (min-width: 1440px) {
  .agent-layout {
    max-width: 1600px;
    margin: 0 auto;
  }
}

/* ─── Mobile preview overlay (desktop only) ─────── */

.mobile-preview-overlay {
  position: fixed;
  inset: 0;
  z-index: 9999;
  background: rgba(0, 0, 0, 0.72);
  backdrop-filter: none;
  display: flex;
  align-items: center;
  justify-content: center;
}

.mobile-preview-phone {
  display: flex;
  flex-direction: column;
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: 24px;
  overflow: hidden;
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.6);
}

.mobile-preview-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  background: var(--bg-tertiary);
  font-size: 12px;
  color: var(--fg-secondary);
  flex-shrink: 0;
}

.mobile-preview-close {
  background: transparent;
  border: none;
  color: var(--fg-secondary);
  font-size: 16px;
  cursor: pointer;
  padding: 2px 6px;
  border-radius: 6px;
  line-height: 1;
  transition: color var(--transition), background var(--transition);
}

.mobile-preview-close:hover {
  background: var(--bg);
  color: var(--fg);
}

.mobile-preview-iframe {
  display: block;
  border: none;
  flex-shrink: 0;
}

/* ================================================= */
/* SUGGESTED REPLY CHIPS                             */
/* ================================================= */

.suggested-replies {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  padding: 10px 16px 4px;
  max-width: 680px;
  animation: suggestFadeIn 0.3s ease forwards;
}

@media (max-width: 767px) {
  .suggested-replies {
    flex-wrap: wrap;
    overflow-x: visible;
    overflow-y: visible;
    -webkit-overflow-scrolling: touch;
    scrollbar-width: none;
    padding: 8px 8px 2px;
    gap: 8px;
    max-width: 100%;
  }
  .suggested-replies::-webkit-scrollbar { display: none; }

  .suggestion-chip {
    flex-shrink: 0;
    font-size: 13px;
    padding: 8px 14px;
    min-height: 36px; /* touch target minimo */
  }
}

@keyframes suggestFadeIn {
  from { opacity: 0; transform: translateY(6px); }
  to   { opacity: 1; transform: translateY(0); }
}

.suggestion-chip {
  display: inline-flex;
  align-items: center;
  padding: 6px 14px;
  border-radius: 20px;
  border: 1px solid var(--border, rgba(255,255,255,0.12));
  background: var(--bg-secondary, rgba(255,255,255,0.04));
  color: var(--fg-secondary, rgba(255,255,255,0.65));
  font-size: 12.5px;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.15s, color 0.15s, border-color 0.15s, transform 0.1s;
  white-space: nowrap;
  line-height: 1;
  letter-spacing: 0.01em;
}

.suggestion-chip:hover {
  background: var(--accent, #3b82f6);
  color: #fff;
  border-color: transparent;
  transform: translateY(-1px);
}

.suggestion-chip:active {
  transform: translateY(0) scale(0.97);
}

/* ================================================= */
/* USER UPLOAD BUBBLE                                */
/* ================================================= */
.upload-bubble {
  padding: 8px 10px !important;
}

.agent-upload-list {
  display: grid;
  gap: 8px;
}

.agent-upload-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 6px 8px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.16);
}

.agent-upload-thumb {
  width: 46px;
  height: 46px;
  border-radius: 8px;
  object-fit: cover;
  flex-shrink: 0;
  border: 1px solid rgba(255, 255, 255, 0.18);
}

.agent-upload-fileicon {
  width: 46px;
  height: 46px;
  border-radius: 8px;
  display: grid;
  place-items: center;
  font-size: 20px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.18);
  flex-shrink: 0;
}

.agent-upload-name {
  font-size: 12px;
  line-height: 1.35;
  color: #f2f6fb;
  word-break: break-word;
}

/* ================================================= */
/* THINKING BUBBLE (animated dots)                   */
/* ================================================= */

.thinking-bubble {
  display: inline-flex !important;
  align-items: center;
  justify-content: center;
  gap: 0;
  width: auto !important;
  min-width: auto !important;
  padding: 8px 12px !important;
  min-height: 0 !important;
}

.typing-indicator {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.thinking-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--fg-secondary, rgba(255,255,255,0.4));
  animation: thinkingPulse 1.3s ease-in-out infinite;
}

.thinking-dot:nth-child(2) { animation-delay: 0.2s; }
.thinking-dot:nth-child(3) { animation-delay: 0.4s; }

@keyframes thinkingPulse {
  0%, 80%, 100% { transform: scale(0.7); opacity: 0.4; }
  40%           { transform: scale(1);   opacity: 1; }
}

/* ================================================= */
/* REAL-TIME CALL MODAL                              */
/* ================================================= */

.realtime-overlay {
  position: fixed;
  inset: 0;
  z-index: 10000;
  background: rgba(0, 0, 0, 0.85);
  backdrop-filter: none;
  display: flex;
  align-items: center;
  justify-content: center;
  animation: realtimeFadeIn 0.2s ease forwards;
}

@keyframes realtimeFadeIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}

.realtime-modal {
  width: min(480px, 92vw);
  min-height: 520px;
  max-height: 86vh;
  background: var(--bg, #0f0f0f);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 24px;
  box-shadow: 0 40px 120px rgba(0,0,0,0.7), 0 0 0 1px rgba(255,255,255,0.04);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  animation: realtimeSlideUp 0.3s cubic-bezier(0.22, 0.61, 0.36, 1) forwards;
}

@keyframes realtimeSlideUp {
  from { opacity: 0; transform: translateY(32px) scale(0.97); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}

.realtime-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 20px 14px;
  border-bottom: 1px solid rgba(255,255,255,0.06);
  flex-shrink: 0;
}

.realtime-status {
  display: flex;
  align-items: center;
  gap: 8px;
}

.realtime-indicator {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: rgba(255,255,255,0.2);
  transition: background 0.3s;
}

.realtime-indicator.is-listening {
  background: #22c55e;
  box-shadow: 0 0 0 3px rgba(34, 197, 94, 0.25);
  animation: listeningPulse 1s ease-in-out infinite;
}

.realtime-indicator.is-speaking {
  background: #3b82f6;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.25);
  animation: speakingPulse 0.8s ease-in-out infinite;
}

@keyframes listeningPulse {
  0%, 100% { box-shadow: 0 0 0 3px rgba(34, 197, 94, 0.25); }
  50%       { box-shadow: 0 0 0 7px rgba(34, 197, 94, 0.08); }
}

@keyframes speakingPulse {
  0%, 100% { box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.25); }
  50%       { box-shadow: 0 0 0 7px rgba(59, 130, 246, 0.08); }
}

.realtime-status-text {
  font-size: 12px;
  color: var(--fg-secondary, rgba(255,255,255,0.45));
  font-weight: 500;
}

.realtime-title {
  font-size: 13px;
  font-weight: 600;
  color: var(--fg, #fff);
  letter-spacing: 0.02em;
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
}

.realtime-close {
  background: rgba(255,255,255,0.06);
  border: none;
  color: var(--fg-secondary, rgba(255,255,255,0.45));
  width: 28px;
  height: 28px;
  border-radius: 50%;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  transition: background 0.15s, color 0.15s;
  line-height: 1;
  margin-left: auto;
}

.realtime-close:hover {
  background: rgba(255,255,255,0.12);
  color: var(--fg, #fff);
}

.realtime-body {
  flex: 1;
  overflow-y: auto;
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  scrollbar-width: thin;
}

.realtime-empty {
  margin: auto;
  text-align: center;
  color: var(--fg-secondary, rgba(255,255,255,0.35));
  font-size: 14px;
  line-height: 1.6;
  max-width: 280px;
  padding: 40px 0;
}

.realtime-bubble {
  max-width: 85%;
  padding: 10px 14px;
  border-radius: 16px;
  font-size: 14px;
  line-height: 1.55;
  word-break: break-word;
  animation: bubblePop 0.2s ease forwards;
}

@keyframes bubblePop {
  from { opacity: 0; transform: scale(0.95); }
  to   { opacity: 1; transform: scale(1); }
}

.realtime-bubble.user {
  align-self: flex-end;
  background: var(--accent, #3b82f6);
  color: #fff;
  border-bottom-right-radius: 4px;
}

.realtime-bubble.agent {
  align-self: flex-start;
  background: rgba(255,255,255,0.07);
  color: var(--fg, rgba(255,255,255,0.9));
  border: 1px solid rgba(255,255,255,0.08);
  border-bottom-left-radius: 4px;
}

.realtime-bubble.is-interim {
  opacity: 0.55;
  font-style: italic;
}

.realtime-controls {
  padding: 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
  border-top: 1px solid rgba(255,255,255,0.06);
  flex-shrink: 0;
}

.realtime-mic-btn {
  position: relative;
  width: 72px;
  height: 72px;
  border-radius: 50%;
  border: none;
  background: rgba(255,255,255,0.08);
  color: rgba(255,255,255,0.7);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.2s, transform 0.15s;
}

.realtime-mic-btn svg {
  width: 28px;
  height: 28px;
  position: relative;
  z-index: 1;
}

.realtime-mic-ring {
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  border: 2px solid transparent;
  transition: border-color 0.2s;
}

.realtime-mic-btn:hover {
  background: rgba(255,255,255,0.13);
  transform: scale(1.05);
}

.realtime-mic-btn.is-active {
  background: #22c55e;
  color: #fff;
}

.realtime-mic-btn.is-active .realtime-mic-ring {
  border-color: rgba(34, 197, 94, 0.4);
  animation: micRing 1.2s ease-in-out infinite;
}

@keyframes micRing {
  0%   { inset: -4px; opacity: 1; }
  100% { inset: -16px; opacity: 0; }
}

.realtime-hint {
  font-size: 12px;
  color: var(--fg-secondary, rgba(255,255,255,0.35));
  text-align: center;
  letter-spacing: 0.02em;
}

/* Realtime button in chat input */
.realtime-btn {
  white-space: nowrap;
  font-size: 11.5px;
  letter-spacing: 0.02em;
  background: transparent;
  border: 1px solid rgba(255,255,255,0.15);
  color: rgba(255,255,255,0.6);
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}

.realtime-btn:hover {
  background: var(--accent, #3b82f6);
  color: #fff;
  border-color: transparent;
}

/* ================================================= */
/* PANEL CALLOUT — mensaje del agente señalando sección */
/* ================================================= */

.panel-callout {
  margin: 8px 8px 0;
  padding: 10px 12px 10px 10px;
  border-radius: 10px;
  background: var(--bg-secondary, rgba(255,255,255,0.05));
  border: 1px solid rgba(255,255,255,0.1);
  display: flex;
  align-items: flex-start;
  gap: 9px;
  position: relative;
  overflow: hidden;
  animation: calloutSlideIn 0.32s cubic-bezier(0.22, 0.61, 0.36, 1) forwards;
  flex-shrink: 0;
}

@keyframes calloutSlideIn {
  from { opacity: 0; transform: translateY(-10px) scale(0.97); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}

/* Borde de color izquierdo según sección */
.panel-callout::before {
  content: '';
  position: absolute;
  left: 0; top: 0; bottom: 0;
  width: 3px;
  border-radius: 10px 0 0 10px;
  background: var(--callout-color, var(--accent, #3b82f6));
}

/* Colores por sección */
.panel-callout-budget       { --callout-color: #22c55e; }
.panel-callout-transactions { --callout-color: #3b82f6; }
.panel-callout-recents      { --callout-color: #a78bfa; }
.panel-callout-library      { --callout-color: #a78bfa; }
.panel-callout-profile      { --callout-color: #f59e0b; }
.panel-callout-news         { --callout-color: #ef4444; }
.panel-callout-objective    { --callout-color: #06b6d4; }
.panel-callout-mode         { --callout-color: #8b5cf6; }

.panel-callout-icon {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  color: var(--callout-color, var(--accent, #3b82f6));
  margin-top: 1px;
}

.panel-callout-icon svg {
  width: 100%;
  height: 100%;
}

.panel-callout-content {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.panel-callout-tag {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--callout-color, var(--accent, #3b82f6));
  line-height: 1;
}

.panel-callout-msg {
  font-size: 12px;
  color: var(--fg, rgba(255,255,255,0.85));
  line-height: 1.45;
  margin: 0;
}

.panel-callout-close {
  background: transparent;
  border: none;
  color: var(--fg-tertiary, rgba(255,255,255,0.28));
  font-size: 16px;
  cursor: pointer;
  padding: 0 2px;
  line-height: 1;
  flex-shrink: 0;
  transition: color 0.15s;
  margin-top: -1px;
  align-self: flex-start;
}

.panel-callout-close:hover {
  color: var(--fg, rgba(255,255,255,0.7));
}

/* Barra de progreso de auto-dismiss */
.panel-callout-progress {
  position: absolute;
  bottom: 0; left: 0;
  height: 2px;
  background: var(--callout-color, var(--accent, #3b82f6));
  opacity: 0.5;
  border-radius: 0 0 10px 10px;
  animation: calloutProgress 7s linear forwards;
  transform-origin: left;
}

@keyframes calloutProgress {
  from { width: 100%; }
  to   { width: 0%; }
}

/* ================================================= */
/* PANEL SECTION HIGHLIGHT                           */
/* ================================================= */

/* Clases genéricas que se aplican a cualquier tarjeta del panel */
.is-panel-highlighted {
  animation: panelSectionGlow 4.5s ease forwards;
  position: relative;
  z-index: 1;
}

@keyframes panelSectionGlow {
  0% {
    box-shadow: none;
    outline: 2px solid transparent;
  }
  8% {
    box-shadow:
      0 0 0 2px var(--highlight-color, rgba(59,130,246,0.6)),
      0 0 16px 4px var(--highlight-color, rgba(59,130,246,0.2));
    outline: 2px solid var(--highlight-color, rgba(59,130,246,0.4));
  }
  55% {
    box-shadow:
      0 0 0 1.5px var(--highlight-color, rgba(59,130,246,0.35)),
      0 0 8px 2px var(--highlight-color, rgba(59,130,246,0.12));
    outline: 2px solid var(--highlight-color, rgba(59,130,246,0.25));
  }
  100% {
    box-shadow: none;
    outline: 2px solid transparent;
  }
}

/* Colores específicos por sección para el highlight */
[data-panel-section="budget"].is-panel-highlighted      { --highlight-color: rgba(34,197,94,0.55); }
[data-panel-section="transactions"].is-panel-highlighted{ --highlight-color: rgba(59,130,246,0.55); }
[data-panel-section="recents"].is-panel-highlighted     { --highlight-color: rgba(167,139,250,0.55); }
[data-panel-section="library"].is-panel-highlighted     { --highlight-color: rgba(167,139,250,0.55); }
[data-panel-section="profile"].is-panel-highlighted     { --highlight-color: rgba(245,158,11,0.55); }
[data-panel-section="news"].is-panel-highlighted        { --highlight-color: rgba(239,68,68,0.55); }
[data-panel-section="objective"].is-panel-highlighted   { --highlight-color: rgba(6,182,212,0.55); }
[data-panel-section="mode"].is-panel-highlighted        { --highlight-color: rgba(139,92,246,0.55); }

/* Pulso sutil en el borde del ítem destacado */
.is-panel-highlighted::after {
  content: '';
  position: absolute;
  inset: -1px;
  border-radius: inherit;
  border: 1.5px solid var(--highlight-color, rgba(59,130,246,0.4));
  pointer-events: none;
  animation: highlightRing 4.5s ease forwards;
  z-index: 10;
}

@keyframes highlightRing {
  0%   { opacity: 0; }
  10%  { opacity: 1; }
  70%  { opacity: 0.5; }
  100% { opacity: 0; }
}

/* Performance-first mobile/tablet tuning */
@media (max-width: 1024px) {
  .agent-layout .agent-bubble,
  .agent-layout .panel-card,
  .agent-layout .recent-library-card,
  .agent-layout .profile-card,
  .agent-layout .agent-input-shell,
  .agent-layout .sheet-tab,
  .agent-layout .smart-chip,
  .agent-layout .context-popover {
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
  }

  .agent-layout .knowledge-rail-fill::after,
  .agent-layout .thinking-dot,
  .agent-layout .voice-waveform-bar,
  .agent-layout .panel-callout,
  .agent-layout .doc-flight,
  .agent-layout .agent-chat.chat-slide-left,
  .agent-layout .agent-chat.chat-slide-right {
    animation: none !important;
  }
}

/* Questionnaire blocks */
.agent-questionnaire-block {
  border: 1px solid rgba(148, 163, 184, 0.22);
  background: rgba(10, 15, 24, 0.62);
  border-radius: 12px;
  padding: 12px;
}

.agent-questionnaire-list {
