}

.latex-inline-questionnaire {
  margin-top: 12px;
}

/* ================================================= */
/* SHEET SYSTEM — Context Score Progress Bar         */
/* ================================================= */

.chat-sheet-tab.is-context {
  opacity: 0.45;
  font-size: 10px;
  padding: 4px 8px;
  background: rgba(201,162,39,0.08);
  border-color: rgba(201,162,39,0.2);
  color: var(--accent-2, #c9a227);
  border-radius: 100px;
}

.chat-sheet-new {
  font-size: 16px;
  font-weight: 300;
  opacity: 0.5;
  color: var(--fg-secondary);
  background: none;
  border: 1px dashed var(--border);
  border-radius: 100px;
  padding: 4px 10px;
  transition: all 0.15s ease;
}

.chat-sheet-new:hover {
  opacity: 1;
  border-color: var(--accent);
  color: var(--accent);
}

.sheet-context-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 3px;
  background: var(--bg-tertiary);
  border-radius: 100px;
  position: relative;
  overflow: visible;
  margin: 4px 0 0;
}

.sheet-context-fill {
  height: 100%;
  border-radius: 100px;
  background: linear-gradient(90deg, #5f7f97, #88a7bc);
  transition: width 0.8s cubic-bezier(0.4, 0, 0.2, 1);
  min-width: 2px;
}

.sheet-context-label {
  position: absolute;
  right: 0;
  top: -18px;
  font-size: 10px;
  color: var(--fg-tertiary);
  white-space: nowrap;
}

.sheet-context-badge {
  position: absolute;
  left: 0;
  top: -18px;
  font-size: 10px;
  font-weight: 600;
  color: var(--accent-2, #c9a227);
  background: var(--accent-2-soft);
  border-radius: 100px;
  padding: 1px 7px;
}

/* ================================================= */
/* VOICE BUBBLE — Floating draggable wide oval       */
/* ================================================= */

/* Bubble is only rendered when open (position set via JS) */
.voice-bubble {
  position: fixed;
  z-index: 9000;
  cursor: grab;
  user-select: none;
}

.voice-bubble:active {
  cursor: grabbing;
}

/* Wide oval container */
.voice-bubble-inner {
  width: 340px;
  background: var(--bg-elevated, #1c1c1e);
  border: 1px solid var(--border);
  border-radius: 56px;
  padding: 14px 20px 14px 24px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  box-shadow: 0 16px 48px rgba(0,0,0,0.32), 0 4px 12px rgba(0,0,0,0.18);
  animation: bubbleExpand 0.38s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  position: relative;
}

/* Morphing blob animation when speaking/listening */
.voice-bubble.is-listening .voice-bubble-inner,
.voice-bubble.is-speaking .voice-bubble-inner {
  animation: blobMorphOval 3s ease-in-out infinite;
}

@keyframes blobMorphOval {
  0%, 100% { border-radius: 56px; }
  25%  { border-radius: 64px 48px 52px 60px / 56px 60px 52px 56px; }
  50%  { border-radius: 48px 64px 60px 52px / 60px 48px 60px 52px; }
  75%  { border-radius: 60px 52px 48px 64px / 52px 64px 48px 60px; }
}

@keyframes bubbleExpand {
  from { opacity: 0; transform: scale(0.6) translateY(20px); }
  to   { opacity: 1; transform: scale(1) translateY(0); }
}

/* Subtle drag-handle dots at top center */
.voice-bubble-drag-handle {
  position: absolute;
  top: 7px;
  left: 50%;
  transform: translateX(-50%);
  width: 32px;
  height: 3px;
  border-radius: 2px;
  background: var(--border);
  opacity: 0.5;
}

.voice-bubble-close {
  position: absolute;
  top: 10px;
  right: 12px;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--bg-tertiary);
  border: none;
  cursor: pointer;
  font-size: 12px;
  color: var(--fg-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.15s ease;
}

.voice-bubble-close:hover {
  background: var(--bg-overlay);
  color: var(--fg);
}

/* Status row — horizontal layout with inline mic */
.voice-bubble-status {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: var(--fg-secondary);
  padding-right: 28px; /* room for close button */
}

.voice-status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--fg-tertiary);
  transition: all 0.3s ease;
}

.voice-status-dot.is-listening {
  background: var(--error, #ff3b30);
  box-shadow: 0 0 0 3px rgba(255,59,48,0.25);
  animation: voicePulse 1s ease-in-out infinite;
}

.voice-status-dot.is-speaking {
  background: var(--success, #34c759);
  box-shadow: 0 0 0 3px rgba(52,199,89,0.25);
  animation: voicePulse 0.8s ease-in-out infinite;
}

@keyframes voicePulse {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.4); }
}

/* Morphing animation when listening */
@keyframes blobMorph {
  0%, 100% { border-radius: 50%; }
  20%  { border-radius: 60% 40% 55% 45% / 50% 55% 45% 50%; }
  40%  { border-radius: 40% 60% 45% 55% / 55% 45% 55% 45%; }
  60%  { border-radius: 55% 45% 60% 40% / 45% 55% 40% 60%; }
  80%  { border-radius: 45% 55% 40% 60% / 60% 40% 60% 40%; }
}

.voice-bubble.is-listening .voice-mic-btn {
  animation: blobMorph 2.5s ease-in-out infinite;
}

/* Transcript */
.voice-bubble-transcript {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 5px;
  max-height: 130px;
  overflow-y: auto;
  scrollbar-width: none;
}

.voice-bubble-transcript::-webkit-scrollbar { display: none; }

.voice-transcript-line {
  font-size: 13px;
  line-height: 1.4;
  padding: 6px 10px;
  border-radius: 12px;
  max-width: 90%;
}

.voice-transcript-user {
  background: var(--accent-soft, rgba(29,58,92,0.12));
  color: var(--fg);
  align-self: flex-end;
  border-radius: 12px 12px 2px 12px;
}

.voice-transcript-agent {
  background: var(--bg-secondary);
  color: var(--fg-secondary);
  align-self: flex-start;
  border-radius: 12px 12px 12px 2px;
}

.voice-transcript-line.is-interim {
  opacity: 0.6;
  font-style: italic;
}

/* Mic button — compact, inline in status row */
.voice-mic-btn {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: var(--accent, #1d3a5c);
  border: none;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  box-shadow: 0 3px 10px rgba(0,0,0,0.22);
  transition: all 0.25s cubic-bezier(0.34, 1.56, 0.64, 1);
  position: relative;
  flex-shrink: 0;
  margin-left: auto;
}

.voice-mic-btn:hover {
  transform: scale(1.08);
  box-shadow: 0 4px 14px rgba(0,0,0,0.28);
}

.voice-mic-btn.is-active {
  background: var(--error, #ff3b30);
}

.voice-mic-btn svg {
  width: 15px;
  height: 15px;
  position: relative;
  z-index: 1;
}

.voice-mic-ring {
  position: absolute;
  inset: -6px;
  border-radius: 50%;
  border: 2px solid transparent;
  transition: all 0.3s ease;
}

.voice-mic-btn.is-active .voice-mic-ring {
  border-color: rgba(255,59,48,0.4);
  animation: micRingPulse 1.2s ease-in-out infinite;
}

@keyframes micRingPulse {
  0%, 100% { transform: scale(1); opacity: 0.6; }
  50% { transform: scale(1.15); opacity: 0.2; }
}

/* ── Voice waveform bars ─────────────────────────── */
.voice-waveform {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 3px;
  height: 28px;
  padding: 4px 0 2px;
  opacity: 0;
  transition: opacity 0.25s ease;
}

.voice-bubble.is-listening .voice-waveform,
.voice-bubble.is-speaking .voice-waveform {
  opacity: 1;
}

.voice-waveform-bar {
  width: 3px;
  border-radius: 3px;
  background: var(--fg-secondary, rgba(255,255,255,0.5));
  transform-origin: center bottom;
  animation: waveBarIdle 2s ease-in-out infinite;
}

.voice-bubble.is-listening .voice-waveform-bar {
  background: var(--error, #ff3b30);
  animation: waveBarListen 0.7s ease-in-out infinite;
}

.voice-bubble.is-speaking .voice-waveform-bar {
  background: var(--accent, #3b82f6);
  animation: waveBarSpeak 0.5s ease-in-out infinite;
}

/* Cada barra tiene su propio delay */
.voice-waveform-bar:nth-child(1)  { animation-delay: 0ms;   height: 8px; }
.voice-waveform-bar:nth-child(2)  { animation-delay: 80ms;  height: 14px; }
.voice-waveform-bar:nth-child(3)  { animation-delay: 160ms; height: 20px; }
.voice-waveform-bar:nth-child(4)  { animation-delay: 80ms;  height: 16px; }
.voice-waveform-bar:nth-child(5)  { animation-delay: 0ms;   height: 10px; }
.voice-waveform-bar:nth-child(6)  { animation-delay: 120ms; height: 18px; }
.voice-waveform-bar:nth-child(7)  { animation-delay: 200ms; height: 22px; }
.voice-waveform-bar:nth-child(8)  { animation-delay: 120ms; height: 16px; }
.voice-waveform-bar:nth-child(9)  { animation-delay: 40ms;  height: 12px; }
.voice-waveform-bar:nth-child(10) { animation-delay: 160ms; height: 8px; }

@keyframes waveBarIdle {
  0%, 100% { transform: scaleY(0.4); opacity: 0.3; }
  50%       { transform: scaleY(1);   opacity: 0.6; }
}

@keyframes waveBarListen {
  0%, 100% { transform: scaleY(0.5); }
  50%       { transform: scaleY(1.3); }
}

@keyframes waveBarSpeak {
  0%, 100% { transform: scaleY(0.7); }
  50%       { transform: scaleY(1.2); }
}

/* ================================================= */
/* PREMIUM MARKDOWN RENDERING                       */
/* ================================================= */

.markdown-content {
  line-height: 1.7;
  color: var(--fg, #1a1a1a);
  letter-spacing: 0.3px;
}

.premium-markdown {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

/* Headings */
.premium-markdown .md-h1 {
  font-size: 2rem;
  font-weight: 600;
  color: var(--fg, #000);
  margin: 1.5rem 0 0.75rem 0;
  letter-spacing: -0.02em;
  border-bottom: 2px solid var(--accent, #3b82f6);
  padding-bottom: 0.5rem;
  font-family: "Iowan Old Style", "Palatino Linotype", "Book Antiqua", Georgia, serif;
  font-style: italic;
  text-wrap: balance;
  line-height: 1.22;
}

.premium-markdown .md-h2 {
  font-size: 1.5rem;
  font-weight: 600;
  color: var(--fg, #1a1a1a);
  margin: 1rem 0 0.5rem 0;
  letter-spacing: -0.01em;
  text-wrap: balance;
  line-height: 1.24;
}

.premium-markdown .md-h3 {
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--fg-secondary, #666);
  margin: 0.75rem 0 0.375rem 0;
  text-wrap: balance;
  line-height: 1.26;
}

.premium-markdown .md-h4,
.premium-markdown .md-h5,
.premium-markdown .md-h6 {
  color: var(--fg, #1a1a1a);
  margin: 0.55rem 0 0.25rem;
  line-height: 1.28;
}

.premium-markdown .md-h4 {
  font-size: 1.08rem;
  font-weight: 750;
}

.premium-markdown .md-h5,
.premium-markdown .md-h6 {
  font-size: 0.98rem;
  font-weight: 700;
  color: var(--fg-secondary, #666);
}

/* Paragraphs */
.premium-markdown .md-paragraph {
  font-size: 1rem;
  margin: 0;
  color: var(--fg, #1a1a1a);
  font-weight: 400;
  text-wrap: pretty;
  line-height: 1.72;
}

/* Text formatting */
.premium-markdown .md-bold {
  font-weight: 700;
  color: var(--fg, #000);
  letter-spacing: 0.2px;
}

.premium-markdown .md-italic {
  font-style: italic;
  color: var(--fg-secondary, #555);
  opacity: 0.95;
}

.premium-markdown .md-code {
  background-color: var(--bg-overlay, rgba(0,0,0,0.05));
  color: var(--error, #ff3b30);
  padding: 0.15rem 0.4rem;
  border-radius: 0.35rem;
  font-family: 'SF Mono', 'Monaco', 'Cascadia Code', monospace;
  font-size: 0.9em;
  font-weight: 500;
  white-space: nowrap;
}

/* Lists */
.premium-markdown .md-list {
  list-style: none;
  margin: 0.5rem 0;
  padding-left: 0;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.premium-markdown .md-list-item {
  position: relative;
  padding-left: 1.75rem;
  font-size: 1rem;
  color: var(--fg, #1a1a1a);
  line-height: 1.6;
}

.premium-markdown .md-list-item::before {
  content: '•';
  position: absolute;
  left: 0.5rem;
  color: var(--accent, #3b82f6);
  font-weight: 700;
  font-size: 1.2rem;
}

/* Links */
.premium-markdown .md-link {
  color: var(--accent, #3b82f6);
  text-decoration: none;
  font-weight: 500;
  border-bottom: 1px solid var(--accent, #3b82f6);
  transition: all 0.2s ease;
  cursor: pointer;
}

.premium-markdown .md-link:hover {
  opacity: 0.8;
  text-decoration: underline;
}

/* ================================================= */
/* ACADEMIC PAPER FORMATTING & MATH SUPPORT         */
/* ================================================= */

.academic-paper {
  background: transparent;
  border-left: 2px solid rgba(120, 190, 255, 0.65);
  padding: 1.5rem;
  border-radius: 8px;
  box-shadow: none;
  font-family: "Open Sans", -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
  max-width: 100%;
}

.academic-paper h1 {
  text-align: center;
  font-size: 2.5rem;
  font-weight: 600;
  margin-bottom: 0.5rem;
  color: var(--fg, #000);
  letter-spacing: -0.03em;
  font-family: "Iowan Old Style", "Palatino Linotype", "Book Antiqua", Georgia, serif;
  font-style: italic;
  text-wrap: balance;
  line-height: 1.2;
}

.academic-paper h2 {
  font-size: 1.8rem;
  font-weight: 700;
  color: var(--fg, #1a1a1a);
  margin-top: 2rem;
  margin-bottom: 1rem;
  border-left: 4px solid var(--accent, #3b82f6);
  padding-left: 1rem;
  page-break-after: avoid;
  text-wrap: balance;
  line-height: 1.24;
}

.academic-paper h3 {
  font-size: 1.4rem;
  font-weight: 600;
  color: var(--fg, #2d2d2d);
  margin-top: 1.5rem;
  margin-bottom: 0.75rem;
  color: var(--accent, #3b82f6);
  page-break-after: avoid;
  text-wrap: balance;
  line-height: 1.28;
}

.academic-paper h4,
.academic-paper h5,
.academic-paper h6 {
  font-weight: 600;
  color: var(--fg, #333);
  margin-top: 1rem;
  margin-bottom: 0.5rem;
}

.agent-thread .premium-markdown .md-h1,
.agent-thread .academic-paper .md-h1 {
  font-size: clamp(1.65rem, 2vw, 2.15rem);
  line-height: 1.15;
  margin: 0.15rem 0 0.85rem;
}

.agent-thread .premium-markdown .md-h2,
.agent-thread .academic-paper .md-h2 {
  font-size: clamp(1.28rem, 1.5vw, 1.55rem);
  line-height: 1.22;
  margin: 1.15rem 0 0.6rem;
}

.agent-thread .premium-markdown .md-h3,
.agent-thread .academic-paper .md-h3 {
  font-size: clamp(1.08rem, 1.2vw, 1.28rem);
  line-height: 1.25;
  margin: 0.85rem 0 0.45rem;
}

.agent-thread .premium-markdown .md-h4,
.agent-thread .premium-markdown .md-h5,
.agent-thread .premium-markdown .md-h6 {
  line-height: 1.28;
  margin: 0.65rem 0 0.3rem;
}

.agent-thread .premium-markdown .md-bold,
.agent-thread .academic-paper .md-bold {
  font-weight: 800;
  color: #ffffff;
}

/* Mathematical Formulas (KaTeX) */
.academic-paper .md-math-block {
  margin: 12px 0;
  overflow-x: auto;
  overflow-y: hidden;
}

.academic-paper .katex-display {
  display: block;
  margin: 1.5rem 0;
  padding: 1rem 1.05rem;
  background: linear-gradient(135deg, rgba(18, 30, 48, 0.52), rgba(8, 16, 28, 0.42));
  border-radius: 10px;
  border: 1px solid rgba(120, 190, 255, 0.25);
  border-left: 3px solid var(--accent, #3b82f6);
  overflow-x: auto;
  position: relative;
  -webkit-overflow-scrolling: touch;
}

.academic-paper .katex-display::before {
  content: 'ℱ';
  position: absolute;
  right: 1rem;
  top: 0.5rem;
  color: var(--accent, #3b82f6);
  opacity: 0.3;
  font-size: 1.5rem;
}

.academic-paper .katex-inline {
  display: inline;
  color: var(--accent, #3b82f6);
  font-weight: 500;
  padding: 0.05em 0.28em;
  background: rgba(59, 130, 246, 0.12);
  border-radius: 4px;
  margin: 0 0.1em;
}

/* Paragraphs and Text */
.academic-paper .md-paragraph {
  text-align: justify;
  font-size: 1.05rem;
  line-height: 1.8;
  margin: 1rem 0;
  color: var(--fg, #2d2d2d);
  font-family: "Open Sans", -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
  text-indent: 1.5rem;
}

/* Chat: forzar monoespaciado en todo el contenido renderizado del agente */
.agent-thread .academic-paper,
.agent-thread .academic-paper *,
.agent-thread .premium-markdown,
.agent-thread .premium-markdown * {
  font-family: "Open Sans", -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif !important;
}

.academic-paper .md-paragraph:first-of-type {
  text-indent: 0;
}

.academic-paper .md-bold {
  font-weight: 700;
  color: var(--fg, #000);
}

.academic-paper .md-italic {
  font-style: italic;
  color: var(--fg, #1a1a1a);
}

/* Code Blocks (for formulas, data, etc.) */
.academic-paper .md-code-block {
  display: block;
  background: rgba(11, 18, 30, 0.52);
  padding: 1rem;
  border-radius: 6px;
  border-left: 3px solid rgba(120, 190, 255, 0.65);
  margin: 1rem 0;
  font-family: 'SF Mono', 'Monaco', 'Cascadia Code', monospace;
  font-size: 0.95rem;
  line-height: 1.6;
  overflow-x: auto;
  white-space: pre-wrap;
  word-break: break-word;
  color: rgba(224, 236, 248, 0.9);
}

.academic-paper .md-code {
  background-color: var(--bg-overlay, rgba(59, 130, 246, 0.12));
  color: var(--accent, #3b82f6);
  padding: 0.2em 0.4em;
  border-radius: 3px;
  font-family: 'SF Mono', 'Monaco', 'Cascadia Code', monospace;
  font-size: 0.92em;
  font-weight: 500;
}

/* Tables (for data presentation) */
.academic-paper .md-table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  margin: 1.4rem 0 1.7rem;
  font-size: 0.96rem;
  line-height: 1.45;
  border: 1px solid rgba(138, 105, 48, 0.28);
  box-shadow:
    0 10px 26px rgba(15, 23, 32, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.65);
  border-radius: 12px;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.84);
}

.academic-paper .md-table thead {
  background: linear-gradient(135deg, #a48f4f 0%, #8a6930 100%);
  color: #ffffff;
}

.academic-paper .md-table thead th {
  padding: 0.8rem 1.05rem;
  text-align: left;
  font-weight: 760;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-size: 0.83rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.24);
}

.academic-paper .md-table tbody tr {
  border-bottom: 1px solid rgba(31, 43, 54, 0.12);
  transition: background-color 0.2s ease;
}

.academic-paper .md-table tbody tr:nth-child(odd) {
  background: rgba(255, 255, 255, 0.92);
}

.academic-paper .md-table tbody tr:nth-child(even) {
  background: rgba(248, 245, 236, 0.72);
}

.academic-paper .md-table tbody tr:hover {
  background-color: rgba(183, 166, 106, 0.16);
}

.academic-paper .md-table tbody td {
  padding: 0.85rem 1.05rem;
  color: #1f2b36;
  vertical-align: top;
  border-right: 1px solid rgba(31, 43, 54, 0.08);
}

.academic-paper .md-table tbody td:last-child,
.academic-paper .md-table thead th:last-child {
  border-right: none;
}

.academic-paper .md-table tbody tr:last-child {
  border-bottom: none;
}

/* Lists */
.academic-paper .md-list,
.academic-paper .md-list-ordered {
  margin: 1rem 0;
  padding-left: 2rem;
}

.academic-paper .md-list-item {
  margin: 0.5rem 0;
  line-height: 1.7;
  color: var(--fg, #2d2d2d);
  text-align: justify;
}

.academic-paper .md-list-item::before {
  color: var(--accent, #3b82f6);
  font-weight: 700;
}

.academic-paper .md-list-ordered {
  list-style: decimal;
}

/* Blockquotes (for citations) */
.academic-paper .md-blockquote {
  border-left: 3px solid rgba(120, 190, 255, 0.48);
  padding: 0.15rem 0 0.15rem 1rem;
  margin: 1rem 0;
  color: #31475c;
  font-style: italic;
  background: transparent;
  border-radius: 0;
}

.academic-paper .md-blockquote p {
  margin: 0.35rem 0;
  text-align: left;
}

/* Links */
.academic-paper .md-link {
  color: var(--accent, #3b82f6);
  text-decoration: none;
  font-weight: 600;
  border-bottom: 2px solid var(--accent, #3b82f6);
  transition: all 0.3s ease;
  cursor: pointer;
  padding-bottom: 2px;
}

.academic-paper .md-link:hover {
  color: #1d4ed8;
  text-decoration: underline;
  border-bottom-color: #1d4ed8;
}

/* ================================================= */
/* AGENT BLOCKS (charts/tables annex)               */
/* ================================================= */

.agent-blocks-renderer {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.agent-block {
  border: none;
  border-radius: 12px;
  padding: 12px;
  background: transparent;
}

.agent-chart-block {
  background:
    linear-gradient(180deg, rgba(244, 238, 228, 0.04), rgba(18, 24, 33, 0.22)),
    repeating-linear-gradient(0deg, rgba(255, 255, 255, 0.03) 0 1px, transparent 1px 16px),
    repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.03) 0 1px, transparent 1px 16px),
    rgba(16, 20, 28, 0.82) !important;
  border: 4px solid rgba(205, 213, 225, 0.32) !important;
  border-radius: 0 !important;
  box-shadow: 8px 8px 0 rgba(8, 10, 16, 0.26) !important;
}

.agent-block h4 {
  margin: 0 0 6px;
  font-size: 14px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.agent-block > p {
  margin: 0 0 10px;
  color: var(--fg-secondary);
  font-size: 12px;
}

.recharts-tooltip-wrapper,
.recharts-tooltip-wrapper *,
.recharts-default-tooltip,
.recharts-default-tooltip *,
.recharts-tooltip-label,
.recharts-tooltip-item,
.recharts-tooltip-item-name,
.recharts-tooltip-item-value,
.agent-chart-tooltip,
.agent-chart-tooltip * {
  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;
}

.agent-chart-canvas {
  width: 100%;
  height: 220px;
}

.agent-chart-footnote {
  margin-top: 8px;
  font-size: 11px;
  color: var(--fg-tertiary);
}

@media (max-width: 767px) {
  .agent-chart-footnote {
    margin-top: 16px !important;
    line-height: 1.35 !important;
  }
}

.agent-table-wrap {
  overflow-x: auto;
}

.agent-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
}

.agent-table th,
.agent-table td {
  border-bottom: 1px solid rgba(148, 163, 184, 0.2);
  padding: 8px;
  text-align: left;
}

.agent-table th {
  color: var(--fg);
  font-weight: 600;
}

.agent-table-note {
  margin-top: 8px;
  font-size: 11px;
  color: var(--fg-tertiary);
}

/* ================================================= */
/* PERFORMANCE MODE (always-on)                      */
/* ================================================= */

.agent-layout,
.agent-chat,
.knowledge-popup,
.doc-bubble {
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  box-shadow: none !important;
}

.agent-chat {
  background: transparent !important;
}

.agent-chat-header,
.agent-chat-body,
.agent-thread,
.chat-pages-outer {
  background: transparent !important;
}

.panel-card,
.profile-card,
.panel-feature-card,
.interview-flow-card,
.recent-library-card {
  background: rgba(20, 26, 38, 0.95) !important;
}

/* Selective Apple glass cards in the right panel */
.glass-card {
  background: rgba(18, 24, 34, 0.24) !important;
  border: 1px solid rgba(255, 255, 255, 0.16) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  box-shadow:
    0 8px 24px rgba(0, 0, 0, 0.25),
    inset 0 1px 0 rgba(255, 255, 255, 0.08) !important;
}

/* Final visual lock for Apple premium panel */
.agent-panel {
  background: rgba(9, 12, 17, 0.52) !important;
  border: 1px solid rgba(255, 255, 255, 0.14) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.28) !important;
}

.agent-panel .panel-card,
.agent-panel .profile-card,
.agent-panel .panel-feature-card,
.agent-panel .interview-flow-card,
.agent-panel .recent-library-card {
  background: rgba(10, 14, 20, 0.84) !important;
  border-color: rgba(255, 255, 255, 0.12) !important;
}

.agent-panel .panel-label,
.agent-panel .profile-badge,
.agent-panel .interview-flow-label {
  color: rgba(200, 220, 236, 0.72) !important;
}

.agent-panel .panel-value,
.agent-panel .profile-name,
.agent-panel .interview-flow-title,
.agent-panel .panel-feature-status {
  color: #ffffff !important;
}

.agent-panel .interview-flow-meta,
.agent-panel .report-group-count,
.agent-panel .report-tag {
  color: #88a7bc !important;
}

.agent-panel .sheet-context-badge,
.agent-panel .chat-sheet-tab.is-context {
  color: #b7a66a !important;
  background: rgba(183, 166, 106, 0.16) !important;
  border-color: rgba(183, 166, 106, 0.34) !important;
}

/* ================================================= */
/* MOBILE LOCK: SMART PANEL AT BOTTOM               */
/* ================================================= */
@media (max-width: 767px) {
  .agent-panel {
    --panel-matte: rgba(8, 12, 18, 0.82);
    --panel-glass: rgba(12, 18, 28, 0.56);
    --panel-border: rgba(188, 216, 238, 0.2);
    --panel-text: rgba(244, 248, 255, 0.95);
    --panel-muted: rgba(176, 196, 214, 0.84);
    --panel-sky: rgba(143, 184, 214, 0.32);
    --panel-warm: rgba(190, 168, 102, 0.24);
  }

  .agent-layout {
    display: flex !important;
    flex-direction: column !important;
    height: 100dvh !important;
    max-height: 100dvh !important;
    padding: 0 !important;
    gap: 0 !important;
  }

  .agent-chat {
    flex: 1 1 auto !important;
    min-height: 0 !important;
    border-radius: 0 !important;
  }

  .agent-divider-rail {
    display: none !important;
  }

  .agent-panel {
    position: relative !important;
    display: block !important;
    flex: 0 0 36dvh !important;
    min-height: 230px !important;
    max-height: 52dvh !important;
    width: 100% !important;
    border-radius: 14px 14px 0 0 !important;
    border-top: 1px solid rgba(255, 255, 255, 0.16) !important;
    border-left: none !important;
    border-right: none !important;
    border-bottom: none !important;
    background: rgba(9, 12, 17, 0.62) !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    overflow: hidden !important;
    margin-top: auto !important;
  }

  .mobile-panel-handle {
    display: none !important;
  }

  .agent-panel .panel-grid {
    display: grid !important;
    grid-template-columns: 1fr 1fr !important;
    gap: 8px !important;
    padding: 10px 10px calc(14px + env(safe-area-inset-bottom)) !important;
    overflow-y: auto !important;
    overflow-x: hidden !important;
    height: 100% !important;
    -webkit-overflow-scrolling: touch !important;
  }

  .agent-panel .mob-col,
  .agent-panel .mob-col-wide,
  .agent-panel .mob-col-narrow {
    width: auto !important;
    min-width: 0 !important;
  }

  .agent-panel .mob-col > * {
    min-height: 88px !important;
    height: auto !important;
  }

  .panel-pos-profile,
  .panel-pos-objective,
  .panel-pos-interview,
  .panel-pos-recent,
  .panel-pos-aux {
    grid-column: 1 / -1 !important;
  }
}

/* Equation numbering and references */
.academic-paper .equation-number {
  position: absolute;
  right: 1rem;
  color: var(--accent, #3b82f6);
  font-weight: 600;
}

/* Abstract Section */
.academic-paper .abstract {
  background-color: var(--bg-overlay, rgba(59, 130, 246, 0.08));
  border-left: 4px solid var(--accent, #3b82f6);
  padding: 1rem;
  margin: 2rem 0;
  border-radius: 6px;
  font-style: italic;
}

/* Print-friendly styles */
@media print {
  .academic-paper {
    box-shadow: none;
    page-break-inside: avoid;
  }
  .academic-paper h2 {
    page-break-after: avoid;
  }
  .academic-paper h3 {
    page-break-after: avoid;
  }
  .academic-paper .md-table {
    page-break-inside: avoid;
  }
  .academic-paper .katex-display {
    page-break-inside: avoid;
  }
}

/* ════════════════════════════════════════════════════════════ */
/* PREMIUM INTERVIEW & CONVERSATION COMPONENTS — Apple Style     */
/* ════════════════════════════════════════════════════════════ */

/* Interview shell - Premium background */
.interview-shell {
  position: relative;
  min-height: 100dvh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px 20px;
  background: linear-gradient(135deg, var(--bg) 0%, var(--bg-secondary) 100%);
  overflow-y: auto;
  overflow-x: hidden;
}

.interview-shell::before {
  content: '';
  position: fixed;
  inset: 0;
  background: radial-gradient(circle at 40% 40%, rgba(42, 123, 176, 0.05), transparent 60%);
  pointer-events: none;
  z-index: 0;
}

.pro-interview-shell {
  background: url('/images/bg-door.jpg') center/cover no-repeat fixed;
}

.pro-interview-shell::before {
  background: radial-gradient(circle at 30% 50%, rgba(0, 0, 0, 0.35), rgba(0, 0, 0, 0.7) 70%);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

.interview-column {
  position: relative;
  z-index: 1;
  width: 100%;
  max-width: 720px;
  display: flex;
  flex-direction: column;
  gap: 0;
}

.pro-interview-column {
  animation: fadeInScale 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

@keyframes fadeInScale {
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

/* Question Card - Premium Glass Design */
.question-card {
  padding: 48px;
  border-radius: 28px;
  background: rgba(255, 255, 255, 0.07);
  border: 1px solid rgba(255, 255, 255, 0.12);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  box-shadow: 0 16px 48px rgba(0, 0, 0, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.1);
  display: flex;
  flex-direction: column;
  gap: 24px;
  animation: cardSlideIn 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

@keyframes cardSlideIn {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.question-card h2 {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.8);
  text-shadow: 0 1px 8px rgba(0, 0, 0, 0.4);
  margin: 0;
}

.question-card p {
  font-size: 20px;
  font-weight: 300;
  letter-spacing: -0.02em;
  line-height: 1.5;
  color: #ffffff;
  text-shadow: 0 2px 12px rgba(0, 0, 0, 0.4);
  margin: 0;
}

.question-card textarea {
  padding: 16px 20px;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.15);
  color: #ffffff;
  font-size: 16px;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  line-height: 1.6;
  resize: vertical;
  min-height: 100px;
  transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

.question-card textarea::placeholder {
  color: rgba(255, 255, 255, 0.5);
}

.question-card textarea:focus {
  outline: none;
  background: rgba(255, 255, 255, 0.12);
  border-color: rgba(42, 123, 176, 0.4);
  box-shadow: 0 0 20px rgba(42, 123, 176, 0.3);
}

.question-card button {
  padding: 16px 32px;
  border-radius: 14px;
  background: linear-gradient(135deg, #ffffff 0%, #f5f5f5 100%);
  color: #000000;
  font-size: 16px;
  font-weight: 600;
  letter-spacing: -0.015em;
  border: none;
  cursor: pointer;
  transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.25), inset 0 1px 0 rgba(255, 255, 255, 0.8);
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  align-self: flex-start;
}

.question-card button:hover:not(:disabled) {
  transform: translateY(-3px);
  box-shadow: 0 16px 48px rgba(0, 0, 0, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.9);
  opacity: 0.98;
}

.question-card button:active:not(:disabled) {
  transform: translateY(-1px);
}

.question-card button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

/* Summary Card - Premium Design */
.summary-card {
  padding: 48px;
  border-radius: 28px;
  background: rgba(255, 255, 255, 0.07);
  border: 1px solid rgba(255, 255, 255, 0.12);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  box-shadow: 0 16px 48px rgba(0, 0, 0, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.1);
  display: flex;
  flex-direction: column;
  gap: 28px;
  animation: cardSlideIn 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.summary-card h2 {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.8);
  text-shadow: 0 1px 8px rgba(0, 0, 0, 0.4);
  margin: 0;
}

.summary-card .summary-content {
  font-size: 18px;
  font-weight: 300;
  letter-spacing: -0.015em;
  line-height: 1.65;
  color: rgba(255, 255, 255, 0.95);
  text-shadow: 0 1px 8px rgba(0, 0, 0, 0.3);
}

.summary-card-actions {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.summary-action-btn {
  padding: 12px 24px;
  border-radius: 12px;
  font-size: 15px;
  font-weight: 500;
  border: none;
  cursor: pointer;
  transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

.summary-action-accept {
  background: linear-gradient(135deg, var(--success) 0%, #2ecc40 100%);
  color: #ffffff;
  box-shadow: 0 8px 24px rgba(52, 199, 89, 0.25);
}

.summary-action-accept:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 32px rgba(52, 199, 89, 0.35);
}

.summary-action-reject {
  background: rgba(255, 255, 255, 0.08);
  border: 1.5px solid rgba(255, 255, 255, 0.15);
  color: #ffffff;
}

.summary-action-reject:hover {
  background: rgba(255, 255, 255, 0.14);
  border-color: rgba(255, 255, 255, 0.28);
  transform: translateY(-2px);
}

/* Mobile responsive — Agent layout */
@media (max-width: 600px) {
  .agent-layout {
    grid-template-columns: 1fr 48px 0px;
    padding: 8px 8px 8px 12px;
    gap: 8px;
  }

  .agent-layout.is-panel-stage-1 {
    grid-template-columns: 1fr 48px 0px;
  }

  .agent-layout.is-panel-stage-2 {
    grid-template-columns: 1fr 48px 0px;
  }

  .agent-layout.is-panel-collapsed,
  .agent-layout.is-panel-stage-small {
    grid-template-columns: 1fr 48px 0px;
  }

  .agent-panel {
    display: none !important;
  }

  .agent-chat {
    border-radius: var(--radius-md);
    box-shadow: none;
    border: none;
  }

  .agent-chat-header {
    padding: 12px 16px;
  }

  .agent-message {
    font-size: 15px;
    line-height: 1.5;
  }

  .agent-chart-canvas {
    max-height: 200px;
  }

  .agent-input-area {
    padding: 8px 12px;
  }
}

/* Extra small devices */
@media (max-width: 400px) {
  .agent-layout {
    padding: 4px 4px 4px 8px;
  }

  .agent-chat-header {
    padding: 10px 12px;
    font-size: 14px;
  }

  .agent-message {
    font-size: 14px;
  }
}

/* Mobile responsive */
@media (max-width: 640px) {
  .question-card,
  .summary-card {
