}

.transactions-modal .tx-analysis-fill {
  position: absolute;
  top: 0;
  left: -36%;
  width: 36%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, rgba(198, 160, 82, 0), rgba(198, 160, 82, 0.95), rgba(142, 167, 191, 0.88), rgba(198, 160, 82, 0));
  animation: txAnalysisSweep 1.35s ease-in-out infinite;
}

@keyframes txAnalysisPulse {
  0%, 100% { transform: scale(1); opacity: 0.88; }
  50% { transform: scale(1.18); opacity: 1; }
}

.transactions-modal .tx-analysis-fill.is-determinate {
  left: 0;
  width: 0;
  animation: none;
  transition: width 420ms ease;
  background: linear-gradient(90deg, rgba(198, 160, 82, 0.92), rgba(142, 167, 191, 0.88));
}

.transactions-modal .tx-analysis-percent {
