  color: rgba(235, 223, 186, 0.92);
  animation: none;
}

.transactions-modal .tx-analysis-step.is-active {
  border-color: rgba(198, 160, 82, 0.72);
  background: rgba(198, 160, 82, 0.18);
  color: rgba(255, 248, 232, 0.98);
  box-shadow: 0 0 0 1px rgba(198, 160, 82, 0.16);
}

.transactions-modal .tx-analysis-step.is-pending {
  opacity: 0.62;
  animation: none;
}

@keyframes txAnalysisSweep {
  0% { left: -36%; }
  100% { left: 100%; }
}

@keyframes txAnalysisStepGlow {
  0%, 100% { border-color: rgba(154, 179, 202, 0.18); opacity: 0.72; }
  50% { border-color: rgba(198, 160, 82, 0.34); opacity: 1; }
}

