    z-index: 4 !important;
  }

  .agent-panel {
    overflow: hidden !important;
  }

  .agent-panel .panel-grid {
    overflow-x: auto !important;
    overflow-y: hidden !important;
    touch-action: pan-x !important;
    -webkit-overflow-scrolling: touch !important;
    overscroll-behavior-x: contain !important;
  }

  .agent-panel.is-dragging {
    transition: none !important;
  }

  .mobile-panel-handle {
    display: flex !important;
    touch-action: none !important;
    flex-shrink: 0 !important;
  }

  .agent-panel.is-mobile-compact {
    position: relative !important;
    overflow: visible !important;
  }

  .agent-panel.is-mobile-compact .panel-callout {
    position: absolute !important;
    left: 0 !important;
    right: 0 !important;
    bottom: calc(100% + 8px) !important;
    margin: 0 !important;
    z-index: 25 !important;
  }

  .agent-panel.is-mobile-expanded .panel-callout {
    position: relative !important;
    left: auto !important;
    right: auto !important;
    bottom: auto !important;
    margin: 8px 8px 0 !important;
  }
}

/* Transactions redesign: intake-like, minimal chat, 3D product hero */
.transactions-modal .tx-content-carousel {
  position: relative;
  perspective: 1400px;
}

.transactions-modal[data-dock-phase] {
  --tx-flood-opacity: 0;
  --tx-surface-shift: 0px;
  --tx-surface-scale: 1;
  --tx-chat-reveal-opacity: 0;
}

.transactions-modal[data-dock-phase="authorizing"] {
  --tx-flood-opacity: 0.24;
  --tx-surface-shift: -10px;
  --tx-surface-scale: 0.992;
}

.transactions-modal[data-dock-phase="flood"] {
  --tx-flood-opacity: 0.86;
  --tx-surface-shift: -22px;
  --tx-surface-scale: 0.978;
}

.transactions-modal[data-dock-phase="library-reveal"] {
  --tx-flood-opacity: 0.34;
  --tx-surface-shift: -12px;
  --tx-surface-scale: 0.988;
}

.transactions-modal[data-dock-phase="chat-reveal"] {
  --tx-flood-opacity: 0.18;
  --tx-chat-reveal-opacity: 1;
}

.transactions-modal .tx-stage-shell {
  isolation: isolate;
}

.transactions-modal .tx-panel-surface {
  position: relative;
  overflow: hidden;
  transform: translate3d(0, var(--tx-surface-shift), 0) scale(var(--tx-surface-scale));
  transition:
    transform 900ms cubic-bezier(.22,.82,.2,1),
    opacity 520ms ease,
    box-shadow 520ms ease,
    border-color 520ms ease;
}

.transactions-modal .tx-panel-surface::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background:
    radial-gradient(circle at 16% 16%, rgba(163, 204, 238, 0.14), transparent 28%),
    linear-gradient(180deg, rgba(255,255,255,0.06), rgba(255,255,255,0) 45%, rgba(255,255,255,0.04));
  opacity: calc(var(--tx-flood-opacity) * 0.75);
  pointer-events: none;
  transition: opacity 520ms ease;
}

.transactions-modal .tx-transition-flood-layer {
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  opacity: var(--tx-flood-opacity);
  transition: opacity 540ms cubic-bezier(.22,.82,.2,1);
  mix-blend-mode: screen;
}

.transactions-modal .tx-transition-flood-layer::before {
  content: "";
  position: absolute;
  inset: -12%;
  background:
    radial-gradient(circle at 18% 24%, rgba(164, 210, 242, 0.26), transparent 28%),
    radial-gradient(circle at 78% 18%, rgba(255, 255, 255, 0.18), transparent 22%),
    radial-gradient(circle at 58% 74%, rgba(197, 162, 86, 0.14), transparent 24%);
  filter: blur(36px);
  transform: scale(1.02);
}

.transactions-modal .tx-digit-dust {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  opacity: 0;
  transition: opacity 360ms ease;
}

.transactions-modal .tx-digit-dust.is-active {
  opacity: 1;
}

.transactions-modal .tx-digit-dust span {
  position: absolute;
  left: var(--dust-x);
  top: var(--dust-y);
  color: rgba(228, 239, 250, 0.72);
  font-family: "SFMono-Regular", Menlo, Consolas, monospace;
  font-size: 11px;
  line-height: 1;
  letter-spacing: 0.02em;
  transform:
    translate3d(-50%, -50%, var(--dust-depth))
    rotate(var(--dust-rotate))
    scale(var(--dust-scale));
  text-shadow: 0 0 20px rgba(143, 189, 223, 0.22);
  animation: txDigitFloat var(--dust-duration) ease-in-out infinite;
  animation-delay: var(--dust-delay);
}

.transactions-modal .tx-digit-dust--flood span {
  color: rgba(233, 245, 255, 0.92);
  font-size: 12px;
}

.transactions-modal .tx-digit-dust--hero,
.transactions-modal .tx-digit-dust--library-card,
.transactions-modal .tx-digit-dust--chat {
  z-index: 1;
  mix-blend-mode: screen;
}

.transactions-modal .tx-digit-dust--hero span,
.transactions-modal .tx-digit-dust--library-card span {
  color: rgba(245, 250, 255, 0.56);
}

.transactions-modal .tx-digit-dust--chat span {
  color: rgba(188, 214, 236, 0.34);
}

@keyframes txDigitFloat {
  0%, 100% {
    opacity: 0.12;
    transform:
      translate3d(-50%, -50%, var(--dust-depth))
      rotate(var(--dust-rotate))
      scale(calc(var(--dust-scale) * 0.92));
  }
  50% {
    opacity: 0.9;
    transform:
      translate3d(-50%, calc(-50% - 14px), calc(var(--dust-depth) + 16px))
      rotate(calc(var(--dust-rotate) * -1))
      scale(calc(var(--dust-scale) * 1.08));
  }
}

