/* =====================================================================
   TRANSACTIONS MODAL — "ULTRA PRO" LAYER
   Premium · matte · opaque · interactive (desktop + mobile)
   Appended last so it wins equal-specificity cascade ties.
   ===================================================================== */
.transactions-modal {
  --txp-panel: #0d141d;
  --txp-panel-edge: #0a1019;
  --txp-surface-1: #131d28;
  --txp-surface-2: #18242f;
  --txp-surface-2-hover: #1f2d3b;
  --txp-border: rgba(150, 180, 205, 0.12);
  --txp-border-strong: rgba(152, 186, 212, 0.22);
  --txp-border-hover: rgba(126, 176, 216, 0.5);
  --txp-text: #e9f1f8;
  --txp-text-dim: #9fb3c4;
  --txp-text-mute: #7f93a4;
  --txp-accent: #5b8cc0;
  --txp-ease: cubic-bezier(0.22, 0.61, 0.36, 1);
}

/* Backdrop — deeper matte vignette, less glossy */
.transactions-modal-overlay {
  background:
    radial-gradient(120% 90% at 50% -10%, rgba(36, 58, 80, 0.34), transparent 60%),
    radial-gradient(100% 80% at 50% 120%, rgba(10, 18, 28, 0.6), transparent 55%),
    rgba(6, 11, 18, 0.74) !important;
  backdrop-filter: blur(10px) saturate(0.9) brightness(0.62) !important;
  -webkit-backdrop-filter: blur(10px) saturate(0.9) brightness(0.62) !important;
  padding: 28px !important;
}

/* The panel itself — a real opaque matte surface */
.transactions-modal {
  background:
    linear-gradient(180deg, var(--txp-panel) 0%, var(--txp-panel-edge) 100%) !important;
  border: 1px solid var(--txp-border-strong) !important;
  border-radius: 28px !important;
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.05) inset,
    0 40px 120px rgba(0, 0, 0, 0.62),
    0 12px 36px rgba(0, 0, 0, 0.45) !important;
  padding-bottom: 8px !important;
  scrollbar-width: thin;
  scrollbar-color: rgba(150, 180, 205, 0.3) transparent;
}
.transactions-modal::-webkit-scrollbar { width: 10px; }
.transactions-modal::-webkit-scrollbar-thumb {
  background: rgba(150, 180, 205, 0.26);
  border-radius: 999px;
  border: 3px solid transparent;
  background-clip: content-box;
}
.transactions-modal::-webkit-scrollbar-thumb:hover { background: rgba(150, 180, 205, 0.42); background-clip: content-box; }

/* Header — premium eyebrow + title + a real close button */
.transactions-modal .bcc-modal-header {
  padding: 26px 28px 0 !important;
  margin-bottom: 6px !important;
}
.transactions-modal .bcc-modal-eyebrow {
  font-size: 11px !important;
  letter-spacing: 0.34em !important;
  text-transform: uppercase;
  font-weight: 600;
  color: var(--txp-accent) !important;
  opacity: 0.9;
}
.transactions-modal .bcc-modal-title {
  font-size: clamp(22px, 2.4vw, 30px) !important;
  font-weight: 700 !important;
  letter-spacing: -0.02em !important;
  color: var(--txp-text) !important;
  margin-top: 4px !important;
}
.transactions-modal .agent-modal-intro {
  padding: 0 28px !important;
  text-align: center !important;
  color: var(--txp-text-dim) !important;
  font-size: 13.5px !important;
  max-width: 760px;
  margin: 6px auto 18px !important;
}
.transactions-modal .agent-modal-close {
  position: absolute !important;
  top: 22px;
  right: 22px;
  width: 38px;
  height: 38px;
  display: inline-flex !important;
  align-items: center;
  justify-content: center;
  border-radius: 12px !important;
  font-size: 20px !important;
  color: var(--txp-text-dim) !important;
  background: var(--txp-surface-2) !important;
  border: 1px solid var(--txp-border) !important;
  transition: transform 0.18s var(--txp-ease), color 0.18s var(--txp-ease),
    background 0.18s var(--txp-ease), border-color 0.18s var(--txp-ease);
}
.transactions-modal .agent-modal-close:hover {
  color: var(--txp-text) !important;
  background: var(--txp-surface-2-hover) !important;
  border-color: var(--txp-border-hover) !important;
  transform: rotate(90deg);
}
.transactions-modal .agent-modal-close:active { transform: rotate(90deg) scale(0.92); }

/* Structural columns — opaque matte raised surfaces */
.transactions-modal .pt-left,
.transactions-modal .pt-right {
  background: var(--txp-surface-1) !important;
  border: 1px solid var(--txp-border) !important;
  border-radius: 22px !important;
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.04) inset,
    0 20px 44px rgba(0, 0, 0, 0.42) !important;
}

/* Inner cards — solid matte tiles with interaction */
.transactions-modal .tx-meta-card,
.transactions-modal .pt-kpi,
.transactions-modal .pt-empty-item,
.transactions-modal .pt-premium-intro {
  background: var(--txp-surface-2) !important;
  border: 1px solid var(--txp-border) !important;
  border-radius: 16px !important;
  box-shadow: none !important;
  transition: border-color 0.18s var(--txp-ease), background 0.18s var(--txp-ease),
    transform 0.18s var(--txp-ease);
}
.transactions-modal .pt-kpi:hover,
.transactions-modal .pt-empty-item:hover {
  background: var(--txp-surface-2-hover) !important;
  border-color: var(--txp-border-strong) !important;
  transform: translateY(-2px);
}
.transactions-modal .tx-meta-card-kicker,
.transactions-modal .pt-kpi span {
  color: var(--txp-text-mute) !important;
}

/* Product card (top of stack) — premium interactive surface */
.transactions-modal .pt-item.pt-item-stack.is-top,
.transactions-modal .pt-item:not(.pt-item-stack) {
  background: var(--txp-surface-2) !important;
  border: 1px solid var(--txp-border-strong) !important;
  border-radius: 20px !important;
  box-shadow: 0 18px 40px rgba(0, 0, 0, 0.4) !important;
  transition: transform 0.2s var(--txp-ease), border-color 0.2s var(--txp-ease),
    box-shadow 0.2s var(--txp-ease), background 0.2s var(--txp-ease);
}
.transactions-modal .pt-item.pt-item-stack.is-top:hover,
.transactions-modal .pt-item:not(.pt-item-stack):hover {
  transform: translateY(-3px);
  border-color: var(--txp-border-hover) !important;
  box-shadow:
    0 24px 54px rgba(0, 0, 0, 0.5),
    0 0 0 1px rgba(126, 176, 216, 0.18) !important;
}

/* Buttons inside the modal — matte, tactile, interactive */
.transactions-modal .continue-ghost {
  background: var(--txp-surface-2) !important;
  border: 1px solid var(--txp-border-strong) !important;
  color: var(--txp-text) !important;
  box-shadow: none !important;
  transition: transform 0.16s var(--txp-ease), background 0.16s var(--txp-ease),
    border-color 0.16s var(--txp-ease);
}
.transactions-modal .continue-ghost:hover:not(:disabled) {
  background: var(--txp-surface-2-hover) !important;
  border-color: var(--txp-border-hover) !important;
  transform: translateY(-1px);
}
.transactions-modal .continue-ghost:active:not(:disabled) { transform: translateY(0) scale(0.98); }

.transactions-modal .tx-preset-btn,
.transactions-modal .tx-minimal-launch-btn,
.transactions-modal .button-primary {
  transition: transform 0.16s var(--txp-ease), box-shadow 0.18s var(--txp-ease),
    filter 0.18s var(--txp-ease) !important;
}
