    width: min(220px, 76%) !important;
    min-height: 130px !important;
  }

  .transactions-modal .tx-3d-sway-wrap.is-floating {
    animation-name: txHeroSwayMobile !important;
  }
}

@keyframes txHeroSwayMobile {
  0%, 100% { transform: perspective(520px) translateX(0px) rotateY(0deg); }
  20%, 28%  { transform: perspective(520px) translateX(-18px) rotateY(7deg); }
  50%       { transform: perspective(520px) translateX(0px) rotateY(0deg); }
  70%, 78%  { transform: perspective(520px) translateX(18px) rotateY(-7deg); }
}

