   ===================================================================== */

@keyframes txCardPulse {
  0% {
    background:
      radial-gradient(circle at 14% 22%, rgba(44, 111, 172, 0.58) 0%, transparent 54%),
      radial-gradient(circle at 84% 18%, rgba(89, 176, 196, 0.26) 0%, transparent 52%),
      radial-gradient(circle at 22% 82%, rgba(201, 168, 64, 0.20) 0%, transparent 56%),
      radial-gradient(circle at 82% 82%, rgba(139, 26, 43, 0.14) 0%, transparent 56%);
  }
  25% {
    background:
      radial-gradient(circle at 14% 22%, rgba(44, 111, 172, 0.18) 0%, transparent 54%),
      radial-gradient(circle at 84% 18%, rgba(89, 176, 196, 0.56) 0%, transparent 52%),
      radial-gradient(circle at 22% 82%, rgba(201, 168, 64, 0.18) 0%, transparent 56%),
      radial-gradient(circle at 82% 82%, rgba(139, 26, 43, 0.14) 0%, transparent 56%);
  }
  50% {
    background:
      radial-gradient(circle at 14% 22%, rgba(44, 111, 172, 0.16) 0%, transparent 54%),
      radial-gradient(circle at 84% 18%, rgba(89, 176, 196, 0.18) 0%, transparent 52%),
      radial-gradient(circle at 22% 82%, rgba(201, 168, 64, 0.54) 0%, transparent 56%),
      radial-gradient(circle at 82% 82%, rgba(139, 26, 43, 0.14) 0%, transparent 56%);
  }
  75% {
    background:
      radial-gradient(circle at 14% 22%, rgba(44, 111, 172, 0.16) 0%, transparent 54%),
      radial-gradient(circle at 84% 18%, rgba(89, 176, 196, 0.18) 0%, transparent 52%),
      radial-gradient(circle at 22% 82%, rgba(201, 168, 64, 0.18) 0%, transparent 56%),
      radial-gradient(circle at 82% 82%, rgba(139, 26, 43, 0.50) 0%, transparent 56%);
  }
  100% {
    background:
      radial-gradient(circle at 14% 22%, rgba(44, 111, 172, 0.58) 0%, transparent 54%),
      radial-gradient(circle at 84% 18%, rgba(89, 176, 196, 0.26) 0%, transparent 52%),
      radial-gradient(circle at 22% 82%, rgba(201, 168, 64, 0.20) 0%, transparent 56%),
      radial-gradient(circle at 82% 82%, rgba(139, 26, 43, 0.14) 0%, transparent 56%);
  }
}

/* Animated step — dark base + cycling radial spotlights */
