/* =====================================================================
   TX-MODAL — Premium fluid transitions pass
   All changes are additive; nothing overrides layout, display, or
   existing keyframes — only adds transition/animation where absent.
   ===================================================================== */

/* 1. Step tabs: smooth border/bg/shadow changes when active state flips */
.transactions-modal .pt-stage {
  transition:
    border-color 260ms cubic-bezier(.22,.82,.2,1),
    background 260ms cubic-bezier(.22,.82,.2,1),
    box-shadow 260ms cubic-bezier(.22,.82,.2,1),
    opacity 220ms ease;
}

/* 2. Library product cards: smooth active + hover state */
.transactions-modal .pt-item {
  transition:
    border-color 260ms cubic-bezier(.22,.82,.2,1),
    box-shadow 260ms cubic-bezier(.22,.82,.2,1),
    transform 260ms cubic-bezier(.22,.82,.2,1),
    background 260ms cubic-bezier(.22,.82,.2,1);
}

/* 3. Analysis loader fade-in when conditionally mounted */
@keyframes txAnalysisAppear {
  0%   { opacity: 0; transform: translateY(8px); }
  100% { opacity: 1; transform: none; }
}
.transactions-modal .tx-analysis-live {
  animation: txAnalysisAppear 320ms cubic-bezier(.22,.82,.2,1);
}

/* 4. Consent section entrance: matches section-1 feel (tx-step-reveal)
      but with a very slight upward drift for the inner content */
.transactions-modal .tx-consent-card {
  animation: txStepReveal 360ms cubic-bezier(.22,.82,.2,1) 40ms both;
}
.transactions-modal .tx-summary-clean .pt-stage-header {
  animation: txStepReveal 280ms cubic-bezier(.22,.82,.2,1);
}
.transactions-modal .tx-consent-card .bank-sim-grid {
  animation: txStepReveal 320ms cubic-bezier(.22,.82,.2,1) 80ms both;
}
.transactions-modal .tx-consent-card .tx-consent-toggle,
.transactions-modal .tx-consent-card .tx-consent-inline-actions {
  animation: txStepReveal 300ms cubic-bezier(.22,.82,.2,1) 120ms both;
}
.transactions-modal .tx-consent-actions-row {
  animation: txStepReveal 280ms cubic-bezier(.22,.82,.2,1) 160ms both;
}

/* 5. Evidence (upload) section staggered inner reveal */
.transactions-modal .tx-evidence-card .tx-upload-onboarding {
  animation: txStepReveal 360ms cubic-bezier(.22,.82,.2,1) 60ms both;
}
.transactions-modal .tx-upload-zone-premium {
  animation: txStepReveal 360ms cubic-bezier(.22,.82,.2,1) 100ms both;
}
.transactions-modal .manual-evidence-block {
  animation: txStepReveal 320ms cubic-bezier(.22,.82,.2,1) 140ms both;
}
.transactions-modal .tx-evidence-card > .agent-modal-actions {
  animation: txStepReveal 280ms cubic-bezier(.22,.82,.2,1) 180ms both;
}

/* 6. Dashboard/analyst section staggered reveal */
.transactions-modal .tx-summary-stage .pt-stage-header {
  animation: txStepReveal 280ms cubic-bezier(.22,.82,.2,1);
}
.transactions-modal .tx-premium-sheet {
  animation: txStepReveal 400ms cubic-bezier(.22,.82,.2,1) 60ms both;
}
.transactions-modal .tx-summary-stage .transactions-summary-card:not(.tx-premium-sheet) {
  animation: txStepReveal 360ms cubic-bezier(.22,.82,.2,1) 80ms both;
}
.transactions-modal .tx-summary-stage > .agent-modal-actions {
  animation: txStepReveal 280ms cubic-bezier(.22,.82,.2,1) 120ms both;
}

/* 7. Format choice buttons smooth hover/active */
.transactions-modal .tx-format-choice {
  transition:
    border-color 200ms ease,
    background 200ms ease,
    box-shadow 200ms ease,
    color 200ms ease;
}

/* 8. Smooth scroll-body opacity on wizard step changes
      — the workspace panel already transitions transform via tx-panel-surface,
        this adds a subtle filter fade for deeper stage feeling */
.transactions-modal .pt-right.tx-panel-surface--workspace {
