/* ── 1180px: compress chart grid to 2 cols ───────────────────────── */
@media (max-width: 1180px) {
  .transactions-modal .tx-ap-chart-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .transactions-modal .tx-ap-chart-card--wide {
    grid-column: span 2;
  }

  .transactions-modal .tx-ap-kpi-secondary-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}

/* ── 820px: stack most grids to 2 cols ───────────────────────────── */
@media (max-width: 820px) {
  .transactions-modal .tx-ap-masthead {
    padding: 22px 18px 18px;
  }

  .transactions-modal .tx-ap-hero-numbers {
    flex-direction: column;
    gap: 18px;
  }

  .transactions-modal .tx-ap-hero-divider {
    width: 100%;
    height: 1px;
    margin: 0;
  }

  .transactions-modal .tx-ap-hero-value {
    font-size: clamp(30px, 8vw, 42px);
  }

  .transactions-modal .tx-ap-hero-secondary {
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 8px 14px;
  }

  .transactions-modal .tx-ap-story-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .transactions-modal .tx-ap-chart-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .transactions-modal .tx-ap-chart-card--wide {
    grid-column: span 1;
  }

  .transactions-modal .tx-ap-intel-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .transactions-modal .tx-ap-kpi-secondary-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .transactions-modal .tx-ap-split-tables {
    grid-template-columns: minmax(0, 1fr);
  }
}

/* ── 480px: full mobile single column ───────────────────────────── */
@media (max-width: 480px) {
  .transactions-modal .tx-ap-dashboard {
    gap: 14px;
  }

  .transactions-modal .tx-ap-masthead {
    padding: 18px 16px 14px;
    border-radius: 16px;
    gap: 16px;
  }

  .transactions-modal .tx-ap-masthead-top {
