    gap: 8px;
  }

  .transactions-modal .tx-ap-hero-value {
    font-size: 34px;
  }

  .transactions-modal .tx-ap-hero-secondary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .transactions-modal .tx-ap-story-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .transactions-modal .tx-ap-story-card {
    padding: 16px 14px 14px;
    border-radius: 14px;
  }

  .transactions-modal .tx-ap-charts-section,
  .transactions-modal .tx-ap-intel-grid,
  .transactions-modal .tx-ap-chart-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .transactions-modal .tx-ap-chart-card {
    min-height: 200px;
  }

  .transactions-modal .tx-ap-kpi-secondary-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .transactions-modal .tx-ap-executive-prose,
  .transactions-modal .tx-ap-intel-card,
  .transactions-modal .tx-ap-chat-dock {
    padding: 16px 14px;
    border-radius: 14px;
  }

  .transactions-modal .tx-ap-footer-actions {
