/* Final lock: product library cards must stay on the exact same x/y center. */
.transactions-modal .pt-list {
  overflow: visible !important;
}

.transactions-modal .pt-stack-carousel.tx-library-is-saved {
  overflow: visible !important;
  position: relative !important;
  isolation: isolate !important;
}

.transactions-modal .pt-stack-carousel.tx-library-is-saved .pt-item.pt-item-stack.tx-lib-card,
.transactions-modal .pt-stack-carousel.tx-library-is-saved .pt-item.pt-item-stack.tx-lib-card.is-top,
.transactions-modal .pt-stack-carousel.tx-library-is-saved .pt-item.pt-item-stack.tx-lib-card:not(.is-top) {
  position: absolute !important;
  top: 50% !important;
  left: 50% !important;
  right: auto !important;
  bottom: auto !important;
  width: calc(100% - 44px) !important;
  max-width: calc(100% - 44px) !important;
  height: calc(100% - 34px) !important;
  transform-origin: center center !important;
  transform:
    translate3d(-50%, -50%, 0)
    scale(calc(1 - (var(--pt-stack-idx, 0) * 0.045)))
    rotate(calc(var(--pt-stack-tilt, 0) * 1deg)) !important;
  animation: none !important;
  transition:
    transform 0.18s ease,
    border-color 0.18s ease,
    box-shadow 0.18s ease,
    opacity 0.18s ease !important;
}

.transactions-modal .pt-stack-carousel.tx-library-is-saved .pt-item.pt-item-stack.tx-lib-card:hover,
.transactions-modal .pt-stack-carousel.tx-library-is-saved .pt-item.pt-item-stack.tx-lib-card:focus-visible,
.transactions-modal .pt-stack-carousel.tx-library-is-saved .pt-item.pt-item-stack.tx-lib-card.is-top:hover {
  transform:
    translate3d(-50%, -50%, 0)
    scale(calc((1 - (var(--pt-stack-idx, 0) * 0.045)) * 1.018))
    rotate(calc(var(--pt-stack-tilt, 0) * 1deg)) !important;
}

.transactions-modal .pt-stack-carousel.tx-library-is-saved .pt-item.pt-item-stack:nth-child(1) {
  --pt-stack-tilt: -0.6;
}

.transactions-modal .pt-stack-carousel.tx-library-is-saved .pt-item.pt-item-stack:nth-child(2) {
  --pt-stack-tilt: -7.5;
}

.transactions-modal .pt-stack-carousel.tx-library-is-saved .pt-item.pt-item-stack:nth-child(3) {
