.transactions-modal .tx-ex-card::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(
    135deg,
    rgba(125, 200, 230, 0.04) 0%,
    transparent 50%,
    rgba(100, 160, 220, 0.02) 100%
