/* ── KEYFRAMES ──────────────────────────────────────────────────────── */

@keyframes bm-overlay-in {
  from { opacity: 0; backdrop-filter: blur(0px); -webkit-backdrop-filter: blur(0px); }
  to   { opacity: 1; backdrop-filter: blur(24px) saturate(0.7) brightness(0.66);
                     -webkit-backdrop-filter: blur(24px) saturate(0.7) brightness(0.66); }
}

@keyframes bm-rise {
  0%   { opacity: 0; transform: perspective(1200px) translateY(48px) rotateX(6deg) scale(0.94); }
  60%  { opacity: 1; transform: perspective(1200px) translateY(-4px) rotateX(-0.5deg) scale(1.006); }
  100% { opacity: 1; transform: perspective(1200px) translateY(0) rotateX(0deg) scale(1); }
}

@keyframes bm-float {
  0%   { opacity: 0; transform: translateY(28px) scale(0.965); }
  65%  { opacity: 1; transform: translateY(-3px) scale(1.004); }
  100% { opacity: 1; transform: translateY(0) scale(1); }
}

@keyframes bm-pop {
  0%   { opacity: 0; transform: translateY(12px) scale(0.78); filter: blur(4px); }
  65%  { opacity: 1; transform: translateY(-2px) scale(1.06); filter: blur(0); }
  100% { opacity: 1; transform: translateY(0) scale(1); filter: blur(0); }
}

@keyframes bm-shimmer {
  0%   { background-position: -280% center; }
  100% { background-position: 280% center; }
}

@keyframes bm-pulse-gold {
  0%, 100% { box-shadow: 0 0 0 0 rgba(219,182,81,0); }
  50%       { box-shadow: 0 0 0 6px rgba(219,182,81,0.07); }
}

@keyframes bm-dot-pulse {
  0%, 80%, 100% { opacity: 0.2; transform: scale(0.7); }
  40%           { opacity: 1;   transform: scale(1); }
}

@keyframes bm-spin {
  to { transform: rotate(360deg); }
}

