/* ── 27. MOBILE ──────────────────────────────────────────────────────── */
@media (max-width: 780px) {
  .budget-modal { border-radius: 24px 24px 0 0 !important; }

  .agent-modal-overlay.budget-modal-overlay { align-items: flex-end !important; }

  .budget-modal .budget-cockpit-banner { border-radius: 16px !important; }

  .budget-modal .budget-assistant-panel,
  .budget-modal .budget-table-section,
  .budget-modal .budget-insights-panel {
    border-radius: 18px !important;
  }

  /* Kill 3D transforms on mobile */
  .budget-modal .budget-assistant-panel:hover,
  .budget-modal .budget-table-section:hover,
  .budget-modal .budget-insights-panel:hover {
    transform: none !important;
  }
  .budget-modal .budget-cockpit-metric:hover,
  .budget-modal .budget-kpi-card:hover {
    transform: translateY(-2px) !important;
  }
  .budget-modal .budget-intel-kpi:hover {
    transform: translateY(-2px) scale(1.01) !important;
  }

  /* Stack KPI cards 2-per-row on mobile */
  .budget-modal .budget-intel-kpis {
    grid-template-columns: repeat(2, 1fr) !important;
  }
  .budget-modal .budget-intel-kpi:nth-child(5) {
    grid-column: span 2 !important;
  }

  /* Larger tap targets */
  .budget-modal .budget-mode-tab {
    padding: 9px 15px !important;
    font-size: 12px !important;
  }
  .budget-modal .bcc-hero-send {
    min-height: 40px !important;
    padding: 0 18px !important;
  }
  .budget-modal .budget-table td,
  .budget-modal .budget-table input,
  .budget-modal .budget-table select {
    font-size: 13px !important;
  }
}

/* ── 28. REDUCED MOTION ──────────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  .budget-modal,
  .budget-modal *,
  .agent-modal-overlay.budget-modal-overlay {
    animation: none !important;
    transition: none !important;
  }
}

