  color: rgba(242,233,223,0.38) !important;
  -webkit-text-fill-color: rgba(242,233,223,0.38) !important;
}

/* Catch-all: any element inside non-PDF atelier with color: #000 or similar */
.budget-modal .budget-table-style-atelier:not(.budget-pdf-surface) {
  color: #f8efe6 !important;
}

/* Also cover the carousel / modal-body wrapping variants */
.budget-modal .budget-modal-body .budget-table-style-atelier:not(.budget-pdf-surface) th,
