/* ═══════════════════════════════════════════════════════════════════════════
   UNIFIED MODAL HEADER SYSTEM — v1.0
   Applies to: .budget-modal, .transactions-modal, .questionnaire-modal
   All three modals share the same header DNA.
   Per-modal color accent is the only differentiation.
   This block lives at the end of agent.css and wins over all prior overrides.
   ─────────────────────────────────────────────────────────────────────────── */

/* ── 0. SHARED TOKENS (cascade-scoped so they don't leak) ──────────────── */
.budget-modal,
.transactions-modal,
.agent-modal.questionnaire-modal {
  --mh-eyebrow-font: "SF Mono", "SFMono-Regular", ui-monospace, Menlo, Consolas, monospace;
  --mh-title-font: -apple-system, BlinkMacSystemFont, "SF Pro Display", "Helvetica Neue", Arial, sans-serif;
  --mh-body-font: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Helvetica Neue", Arial, sans-serif;
  --mh-bg: rgba(6, 8, 14, 0.92);
  --mh-blur: blur(22px);
  --mh-border: rgba(255,255,255,0.10);
  --mh-title-color: rgba(248, 248, 252, 0.97);
  --mh-intro-color: rgba(210, 224, 244, 0.60);
  --mh-close-bg: rgba(255,255,255,0.06);
  --mh-close-bg-hover: rgba(255,255,255,0.13);
  --mh-close-color: rgba(220,232,248,0.55);
  --mh-close-color-hover: rgba(248,248,252,0.97);
}

/* Per-modal accent (eyebrow color) */
.budget-modal            { --mh-accent: rgba(219, 182,  81, 0.88); }
.transactions-modal      { --mh-accent: rgba(106, 173, 244, 0.88); }
.agent-modal.questionnaire-modal { --mh-accent: rgba( 74, 222, 128, 0.82); }

/* ── 1. HEADER CONTAINER ────────────────────────────────────────────────── */
.budget-modal .bcc-modal-header,
.transactions-modal .bcc-modal-header,
.agent-modal.questionnaire-modal .bcc-modal-header {
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  padding: 22px 28px 20px !important;
  background: var(--mh-bg) !important;
  backdrop-filter: var(--mh-blur) !important;
  -webkit-backdrop-filter: var(--mh-blur) !important;
  border-bottom: 1px solid var(--mh-border) !important;
  border-radius: 24px 24px 0 0 !important;
  position: relative !important;
  z-index: 2 !important;
}

/* ── 2. TITLE WRAP ──────────────────────────────────────────────────────── */
.budget-modal .bcc-modal-title-wrap,
.transactions-modal .bcc-modal-title-wrap,
.agent-modal.questionnaire-modal .bcc-modal-title-wrap {
  display: flex !important;
  flex-direction: column !important;
  gap: 5px !important;
}

/* ── 3. EYEBROW — "Financieramente" ─────────────────────────────────────── */
.budget-modal .bcc-modal-eyebrow,
.transactions-modal .bcc-modal-eyebrow,
.agent-modal.questionnaire-modal .bcc-modal-eyebrow {
  display: block !important;
  font-family: var(--mh-eyebrow-font) !important;
  font-size: 9.5px !important;
  font-weight: 600 !important;
  letter-spacing: 0.22em !important;
  text-transform: uppercase !important;
  font-style: normal !important;
  color: var(--mh-accent) !important;
  -webkit-text-fill-color: var(--mh-accent) !important;
  background: none !important;
  -webkit-background-clip: unset !important;
  background-clip: unset !important;
  animation: none !important;
  margin: 0 !important;
  line-height: 1 !important;
}

/* ── 4. TITLE ────────────────────────────────────────────────────────────── */
.budget-modal .bcc-modal-title,
.transactions-modal .bcc-modal-title,
.agent-modal.questionnaire-modal .bcc-modal-title {
  font-family: var(--mh-title-font) !important;
  font-size: 17px !important;
  font-weight: 600 !important;
  letter-spacing: -0.028em !important;
  line-height: 1.15 !important;
  color: var(--mh-title-color) !important;
  -webkit-text-fill-color: var(--mh-title-color) !important;
  background: none !important;
  -webkit-background-clip: unset !important;
  background-clip: unset !important;
  margin: 0 !important;
}

/* ── 5. INTRO / SUBTITLE ────────────────────────────────────────────────── */
.budget-modal .agent-modal-intro,
.transactions-modal .agent-modal-intro,
.agent-modal.questionnaire-modal .agent-modal-intro {
  font-family: var(--mh-body-font) !important;
  font-size: 12.5px !important;
  font-weight: 400 !important;
  letter-spacing: -0.005em !important;
  line-height: 1.5 !important;
  color: var(--mh-intro-color) !important;
  -webkit-text-fill-color: var(--mh-intro-color) !important;
  padding: 10px 28px 0 !important;
  margin: 0 !important;
  text-align: left !important;
  max-width: none !important;
}

/* ── 6. CLOSE BUTTON ────────────────────────────────────────────────────── */
.budget-modal .agent-modal-close,
.transactions-modal .agent-modal-close,
.agent-modal.questionnaire-modal .agent-modal-close {
  position: relative !important;
  top: auto !important;
  right: auto !important;
  flex-shrink: 0 !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  width: 32px !important;
  height: 32px !important;
  min-width: 32px !important;
  padding: 0 !important;
  border-radius: 50% !important;
  background: var(--mh-close-bg) !important;
  border: 1px solid rgba(255,255,255,0.10) !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  color: var(--mh-close-color) !important;
  -webkit-text-fill-color: var(--mh-close-color) !important;
  font-size: 16px !important;
  font-weight: 300 !important;
  line-height: 1 !important;
  cursor: pointer !important;
  transition:
    background 0.18s ease,
    border-color 0.18s ease,
    color 0.18s ease,
    transform 0.22s cubic-bezier(0.22, 1, 0.36, 1) !important;
}

.budget-modal .agent-modal-close:hover,
.transactions-modal .agent-modal-close:hover,
.agent-modal.questionnaire-modal .agent-modal-close:hover {
  background: var(--mh-close-bg-hover) !important;
  border-color: rgba(255,255,255,0.18) !important;
  color: var(--mh-close-color-hover) !important;
  -webkit-text-fill-color: var(--mh-close-color-hover) !important;
  transform: rotate(90deg) scale(1.1) !important;
  box-shadow: none !important;
}

.budget-modal .agent-modal-close:active,
.transactions-modal .agent-modal-close:active,
.agent-modal.questionnaire-modal .agent-modal-close:active {
  transform: rotate(90deg) scale(0.92) !important;
}

/* SVG inside close button (budget uses inline SVG) */
.budget-modal .agent-modal-close svg,
.transactions-modal .agent-modal-close svg,
.agent-modal.questionnaire-modal .agent-modal-close svg {
  width: 13px !important;
  height: 13px !important;
  stroke: currentColor !important;
  color: inherit !important;
}

/* ── 7. MOBILE ──────────────────────────────────────────────────────────── */
@media (max-width: 780px) {
  .budget-modal .bcc-modal-header,
  .transactions-modal .bcc-modal-header,
  .agent-modal.questionnaire-modal .bcc-modal-header {
    padding: 18px 20px 16px !important;
    border-radius: 20px 20px 0 0 !important;
  }

  .budget-modal .bcc-modal-title,
  .transactions-modal .bcc-modal-title,
  .agent-modal.questionnaire-modal .bcc-modal-title {
    font-size: 16px !important;
  }

  .budget-modal .agent-modal-intro,
  .transactions-modal .agent-modal-intro,
  .agent-modal.questionnaire-modal .agent-modal-intro {
    padding: 8px 20px 0 !important;
    font-size: 12px !important;
  }
}


