.ai-loader-shell {
  position: relative;
  min-height: 84vh;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  background:
    radial-gradient(circle at 20% 18%, rgba(118, 160, 205, 0.16), transparent 28%),
    radial-gradient(circle at 80% 14%, rgba(186, 212, 236, 0.1), transparent 24%),
    linear-gradient(180deg, rgba(7, 12, 20, 0.96), rgba(3, 8, 14, 0.98));
}

.ai-loader-shell::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, transparent 0%, rgba(255, 255, 255, 0.018) 50%, transparent 100%);
  opacity: 0.55;
  pointer-events: none;
}

.ai-loader-center {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 18px;
  padding: 32px;
}

.ai-loader-orbit {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.ai-loader-ring,
.ai-loader-glow {
  position: absolute;
  inset: 0;
  border-radius: 999px;
}

.ai-loader-ring {
  animation: aiLoaderSpin 5.2s linear infinite;
  box-shadow:
    0 6px 12px 0 rgba(112, 181, 231, 0.72) inset,
    0 16px 26px 0 rgba(60, 109, 184, 0.76) inset,
    0 34px 38px 0 rgba(13, 35, 74, 0.88) inset,
    0 0 24px rgba(89, 161, 221, 0.16);
}

.ai-loader-glow {
  inset: 18%;
  background: radial-gradient(circle, rgba(156, 198, 233, 0.22), transparent 62%);
  filter: blur(18px);
}

.ai-loader-copy {
